function accessError(input,text,valid=false){
 const hint=document.getElementById(input.id+'-hint');
 input.setAttribute('aria-invalid',String(!!text&&!valid));input.dataset.formatValid=String(valid);
 if(hint){hint.textContent=(valid?'✓ ':'')+text;hint.classList.toggle('valid',valid);}
 if(input.form?.id==='login-form')paintLoginState(input);
}
// Acceso: estado visual de cada campo (azul sin interacción, ámbar mientras se escribe o falta completar, rojo con error confirmado,
// verde con formato local válido). Solo valida el formato en el navegador: no consulta al servidor ni afirma que un dato sea correcto.
const loginGlyphs={typing:'M12 20h9 M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4z',filled:'M6 12h.01 M12 12h.01 M18 12h.01',valid:'M5 12.5l4.5 4.5L19 7.5',error:'M12 8v5 M12 16.5h.01 M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18z',ok:'M8 12.5l3 3 5-6 M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18z'};
function setLoginState(input,state,text){const box=input.closest('.login-input'),hint=document.getElementById(input.id+'-hint');if(!box)return;box.dataset.state=state;let mark=box.querySelector('.login-state');if(!mark){mark=document.createElement('i');mark.className='login-state';mark.setAttribute('aria-hidden','true');box.append(mark);}mark.replaceChildren();if(loginGlyphs[state])mark.append(systemIcon(loginGlyphs[state]));if(hint&&text!==undefined){hint.textContent=text;hint.dataset.state=state;hint.classList.toggle('valid',state==='valid'||state==='ok');}}
function paintLoginState(input){const value=input.name==='password'?input.value:input.value.trim();
 if(input.name==='password'&&value.length>=input.maxLength)return setLoginState(input,'typing','Has alcanzado el máximo de '+input.maxLength+' caracteres.');
 if(input.name==='login'&&!value.includes('@')&&value.length>50)return setLoginState(input,'error','El usuario admite hasta 50 caracteres.');
 if(input.name==='login'&&value.length>=input.maxLength)return setLoginState(input,'typing','Has alcanzado el máximo de '+input.maxLength+' caracteres.');
 const focused=input.dataset.focused==='true',submitted=input.form.dataset.submitted==='true',invalid=input.getAttribute('aria-invalid')==='true';
 if(!value)return setLoginState(input,invalid?'error':'idle');
 if(input.name==='password')return setLoginState(input,focused?'typing':'filled',focused?'Escribiendo…':'Contraseña introducida.');
 if(value.includes('@')){if(!invalid)return setLoginState(input,'valid','✓ Formato de correo válido.');if(focused&&!submitted){input.setAttribute('aria-invalid','false');return setLoginState(input,'typing','Completa el correo electrónico.');}return setLoginState(input,'error','Revisa el formato del correo electrónico.');}
 if(/\s/.test(value))return setLoginState(input,focused&&!submitted?'typing':'error','El usuario no lleva espacios.');
 if(value.length<3)return setLoginState(input,'typing','Usuario incompleto.');
 return setLoginState(input,'valid','✓ Formato válido.');}
function loginOutcome(form,state){for(const input of [form.elements.login,form.elements.password])setLoginState(input,state,state==='ok'?'':undefined);}
function checkAccessField(input,submitted=false){
 const value=input.type==='password'||input.name==='repeat'?input.value:input.value.trim();
 if(!value){accessError(input,submitted?(input.name==='login'?'Escribe tu usuario o correo electrónico.':input.name==='email'?'Introduce tu correo electrónico.':input.name==='password'?'Escribe tu contraseña.':'Completa este campo.'):'');return !submitted;}
 if(input.name==='login'||input.name==='email'){
  if(input.name==='email'||value.includes('@')){const valid=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);accessError(input,valid?'Formato de correo correcto.':'Revisa el formato del correo electrónico.',valid);return valid;}
 }
 if(input.name==='username'&&!/^[a-zA-Z0-9_.-]{3,50}$/.test(value)){accessError(input,'Usa de 3 a 50 letras, números, punto, guion o guion bajo.');return false;}
 if(['reset','register'].includes(document.body.dataset.page)){
  if(input.name==='password'&&value.length<Number(input.minLength)){accessError(input,'Usa al menos '+input.minLength+' caracteres.');return false;}
  if(input.name==='repeat'){const valid=input.value===document.getElementById('password').value;accessError(input,valid?'Las contraseñas coinciden.':'Las contraseñas no coinciden.',valid);return valid;}
 }
 accessError(input,'');return true;
}
function validateAccess(form){form.dataset.submitted='true';let first;form.querySelectorAll('input[required]').forEach(input=>{if(!checkAccessField(input,true)&&!first)first=input;});if(first)first.focus();return !first;}
document.querySelectorAll('.access-card input[required]').forEach(input=>{
 input.addEventListener('input',()=>{checkAccessField(input);if(document.body.dataset.page==='reset'&&input.name==='password'){
 const score=input.value.length<Number(input.minLength)?0:Math.min(4,Math.max(1,1+Math.floor((input.value.length-12)/6)+(new Set(input.value).size>=10?1:0)));
 document.getElementById('password-strength').value=score;document.getElementById('strength-text').textContent=['Demasiado corta','Fortaleza baja','Fortaleza media','Fortaleza alta','Frase o contraseña larga'][score];
 const repeat=document.getElementById('repeat');if(repeat.value)checkAccessField(repeat);
 }});
 input.addEventListener('blur',()=>{if(input.name==='login'||input.name==='email')input.value=input.value.trim();checkAccessField(input,input.form?.dataset.submitted==='true'||!!input.value);});
});
