 function paintSound(){sound.replaceChildren(operationIcon(prefs.sound?'sound':'muted'));sound.setAttribute('aria-pressed',String(prefs.sound));sound.setAttribute('aria-label',prefs.sound?'Sonido de notificaciones activado. Pulsar para silenciar':'Sonido de notificaciones silenciado. Pulsar para activar');sound.title=prefs.sound?'Silenciar sonido':'Activar sonido';}
