  const total=state.total??state.items.length;$('notify-summary').textContent=count+' sin leer · '+total+' en total';$('notify-summary').dataset.count=String(count);$('notify-read').disabled=!count;$('notify-read').textContent=count?'Marcar todas como leídas':'Todo está leído';list.replaceChildren();
  if(!state.items.length||!count&&!state.items.some(item=>new Date(item.at).getTime()>=Date.now()+clockOffset-86400000)){const empty=el('div',undefined,'notify-empty');empty.append(operationIcon('bell'),el('strong','No tienes notificaciones pendientes'),el('p',total?'Puedes revisar el historial completo en el Centro de notificaciones.':'Aquí verás licencias, órdenes, citas, correos y avisos del sistema.'));list.append(empty);return;}
  // Vista compacta: un renglón por categoría con los eventos reales agrupados; cada evento conserva su enlace y su estado de lectura.
  const groups=noticeGroups(state.items).filter(group=>group.unread||group.items.some(item=>new Date(item.at).getTime()>=Date.now()+clockOffset-86400000));
  if(!groups.length){list.append(el('p','No hay novedades recientes.','notify-quiet'));return;}
