 tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','Filtrar la actividad');search.type='search';search.placeholder='Buscar';search.maxLength=80;search.setAttribute('aria-label','Buscar en la actividad');from.type='date';from.title='Desde la fecha';from.setAttribute('aria-label','Desde la fecha');readAll.append(systemIcon('M18 6 7 17l-5-5 M22 10l-7.5 7.5L13 16'),el('span','Marcar todo como leído'));
 detail.hidden=true;detail.setAttribute('aria-label','Detalle del aviso');detail.tabIndex=-1;const hiddenButton=button('Ver ocultas',()=>showHidden(),'text-action activity-hidden-open');bar.append(tabs,search,from,readAll,hiddenButton);layout.append(list,detail);
 const header=el('header',undefined,'activity-head');header.append(el('p','','activity-count'));header.firstChild.setAttribute('aria-live','polite');wrap.append(header,cards,risk,bar,layout,note);root.replaceChildren(wrap);
 const tabDefs=[['all','Todas',()=>true],['unread','Sin leer',item=>!item.read],['licenses','Licencias',item=>noticeCategory(item)==='licenses'],['orders','Órdenes',item=>noticeCategory(item)==='orders'],['appointments','Citas',item=>noticeCategory(item)==='appointments'],['mail','Correos',item=>noticeCategory(item)==='mail'],['chat','Conversaciones',item=>noticeCategory(item)==='chat'],['system','Sistema',item=>['system','alerts'].includes(noticeCategory(item))]];
 const iconOf=item=>noticeCritical(item)?noticeDatabase:noticeCategories[noticeCategory(item)].icon;
 async function mark(key){try{data=await api('/api/notifications/read',key?{keys:key}:{all:true});paint();document.dispatchEvent(new CustomEvent('notices:changed'));}catch(error){toast(error.message,'error');}}
 async function hide(key){try{data=await api('/api/notifications/hide',{keys:key});paint();document.dispatchEvent(new CustomEvent('notices:changed'));toast('Aviso oculto. Puedes recuperarlo en «Ver ocultas».','success',{label:'Deshacer',run:()=>restore(key)});}catch(error){toast(error.message,'error');}}
