 initOrderSearch();
 formAction('order-form',async(form,data)=>{
  if(wizardStep!==WIZARD_LAST){advanceWizard();return;}
  if(form.dataset.saving==='true')return;
  const errors=validateReception(data);setOrderErrors(errors);if(Object.keys(errors).length){const error=new Error(orderErrorSummary(errors));error.fields=errors;throw error;}
  data.terms_accept=form.elements.terms_accept.checked;Object.assign(data,accessPayload(form));data.request_key=form.dataset.requestKey;Object.assign(data,equipmentPayload());form.dataset.saving='true';
  // Solo se bloquean (y luego se liberan) los botones que estaban activos: los demás conservan su estado.
  const locked=[...form.querySelectorAll('button[type=button]')].filter(b=>!b.disabled),unlock=()=>locked.forEach(b=>{if(b.isConnected)b.disabled=false;});locked.forEach(b=>b.disabled=true);
  let saved;
  try{saved=await api('/api/orders',data);}catch(error){if(error.status===409&&error.fields?.terms_accept)await loadCurrentTerms();form.dataset.saving='false';unlock();
   // El servidor rechazó algún dato: se señala el campo, se vuelve a su paso y se explica cuál es. Nada se borra.
   if(error.fields&&Object.keys(error.fields).length){setOrderErrors(error.fields);paintWizardStepper();error.message=orderErrorSummary(error.fields)||error.message;}else if(!error.status)error.message='No se pudo guardar la orden: sin conexión con el servidor. Los datos y las fotos se conservan; inténtalo de nuevo.';throw error;}
  // La orden ya existe: las fotos se suben a continuación y un fallo de subida no la invalida.
  let failedPhotos=0;const status=$('order-upload-status'),total=orderPhotos.length;
  try{if(total)failedPhotos=await uploadOrderPhotos(saved.id,orderPhotos,index=>{status.textContent='Orden '+saved.code+' registrada. Subiendo foto '+(index+1)+' de '+total+'…';});}finally{status.textContent='';form.dataset.saving='false';unlock();}
  const addedTo=receptionGroup;clearOrderDraft();resetReception();$('order-dialog').close();
  receptionLoading=null;try{await loadReceptionOptions();updateBrands();}catch(error){/* Se reintentará al abrir el siguiente formulario. */receptionOptions=null;}
  history.replaceState(null,'','/#orders');await renderRoute();notify((addedTo?'Equipo '+saved.code+' agregado a la orden '+addedTo.code:'Orden '+saved.code+' registrada correctamente')+(total?(failedPhotos?' con '+(total-failedPhotos)+' de '+total+' fotos':' con '+(total===1?'1 foto':total+' fotos')):'')+'.',true);if(failedPhotos)toast(failedPhotos+(failedPhotos===1?' foto no se pudo subir.':' fotos no se pudieron subir.')+' Añádelas desde el detalle de la orden.','warning');/* El servidor ya intentó el envío al guardar la orden; aquí solo se informa su resultado. */if(saved.receipt_mail)receiptMailToast(saved.id,saved.receipt_mail);else sendReceiptMail(saved.id,'auto');await showReceipt(saved.id);
 });
