function systemChanges(release,categories){const wrap=el('div',undefined,'system-changes');let any=false;for(const [key,title] of Object.entries(categories)){const items=release.changes[key]||[];if(!items.length)continue;any=true;const group=el('section',undefined,'system-change-group');group.dataset.category=key;const heading=el('h4');heading.append(systemIcon(systemIcons[key]),el('span',title),el('span',String(items.length),'system-count'));const list=el('ul');items.forEach(item=>list.append(el('li',item)));group.append(heading,list);wrap.append(group);}if(!any)wrap.append(el('p','Sin cambios detallados en esta versión.','system-muted'));return wrap;}
