 for(const key of Object.keys(data.categories)){const total=(release.changes[key]||[]).length;if(!total)continue;const chip=el('span',undefined,'version-count');chip.dataset.category=key;chip.title=data.categories[key];chip.append(systemIcon(systemIcons[key]),el('span',total+' '+short[key][total===1?0:1]));tally.append(chip);}
