 const panel=el('div',undefined,'release-panel');panel.id='release-panel';panel.hidden=true;panel.setAttribute('role','dialog');panel.setAttribute('aria-label','Estado de la versión');document.body.append(panel);
 const wide=matchMedia('(min-width: 1000px)'),placeChip=()=>{if(wide.matches)document.querySelector('.header-utilities').prepend(chip);else $('header-drawer').append(chip);if(!panel.hidden)setOpen(false);};wide.addEventListener('change',placeChip);placeChip();
 let open=false,announced='',shownIcon='layers';
 // Icono según el estado real: capas (al día), sincronización (comprobando o actualizando), flecha (versión nueva), visto (completada) y alerta (error).
 const icons={layers,sync,up:'<circle cx="12" cy="12" r="10"/><path d="m16 12-4-4-4 4"/><path d="M12 16V8"/>',check:'<circle cx="12" cy="12" r="10"/><path d="m9 12 2 2 4-4"/>',alert:'<circle cx="12" cy="12" r="10"/><path d="M12 8v4"/><path d="M12 16h.01"/>'};
 function setIcon(name){if(shownIcon===name)return;shownIcon=name;icon.innerHTML=icons[name];icon.classList.remove('release-icon-swap');void icon.getBoundingClientRect();icon.classList.add('release-icon-swap');}
 const labels={idle:'Sin comprobar',working:'Comprobando…',ok:'Actualizado',pending:'Nueva versión disponible',error:'Error de comprobación'};
