  try{const out=await api('/api/autocare/check',{code:item.code});const r=out.result;toast(item.name+': '+autocareStatus[r.status][0]+' · '+r.detail,r.status==='ok'?'success':r.status==='error'?'error':'info');await renderAutoCare(box,out.overview);box.querySelector('#ac-retry-'+item.code)?.focus();}
