  fact('Estado',M.state);fact('Configuración',M.configured?'Completa':'Incompleta');fact('Servidor IMAP',M.imap||'—');fact('Servidor SMTP',M.smtp||'—');fact('Cuenta',M.account||'—');fact('Contraseña',M.password_set?'Definida (no se muestra)':'No definida');
  fact('Última comprobación del buzón',M.last_check?formatOrderDate(M.last_check.at)+' · '+(M.last_check.source==='manual'?'manual':'programada')+' · '+(M.last_check.status==='ok'?'Correcta':'Fallo real')+' · '+M.last_check.detail:'Ninguna todavía (comprobación pendiente)');
