 const longDate=value=>{const date=new Date(value);return Number.isNaN(date.getTime())?'No registrada':new Intl.DateTimeFormat('es-EC',{timeZone:'America/Guayaquil',day:'numeric',month:'long',year:'numeric',hour:'numeric',minute:'2-digit'}).format(date);};
