 const mark=el('span',undefined,'system-mark');mark.append(systemIcon(systemIcons.version));const info=el('div',undefined,'system-current');const product=el('h2',installed?'Órdenes Pro '+installed.version:'Sin versiones registradas');product.id='system-product';
 const facts=el('dl',undefined,'system-lines');const line=(label,node)=>{const row=el('div');const dd=el('dd');dd.append(node);row.append(el('dt',label),dd);facts.append(row);};
 const published=el('span',installed?'Publicada':'No registrada','system-chip');published.dataset.state=installed?'ok':'idle';if(installed)published.prepend(systemIcon(systemIcons.ok));
 line('Estado',published);line('Última publicación',installed?longDate(installed.date):'No registrada');line('Tipo de actualización',installed?(data.types[installed.type]||'—'):'—');line('Versiones registradas',String(data.releases.length));
 info.append(el('span','Versión actual del sistema','system-label'),product,facts);card.append(mark,info);
 const checker=el('section',undefined,'data-panel system-checker');checker.setAttribute('aria-labelledby','system-check-title');const checkHead=el('div',undefined,'system-checker-head'),checkTitle=el('h2','Estado de actualizaciones');checkTitle.id='system-check-title';const checkLead=el('div',undefined,'system-checker-lead');checkLead.append(checkTitle,el('p','Control de versiones y comprobación automática','system-muted'));const chip=el('span','Sin comprobar','system-chip');chip.id='system-state';chip.dataset.state='idle';checkHead.append(checkLead,chip);
 const bar=el('div',undefined,'system-bar'),fill=el('span');bar.setAttribute('role','progressbar');bar.setAttribute('aria-label','Estado de la comprobación de actualizaciones');bar.append(fill);bar.dataset.state='idle';
 const stages=el('ol',undefined,'system-stages');['Consultando versiones','Comparando versiones','Mostrando el resultado'].forEach(label=>stages.append(el('li',label)));
 // Pinta el estado real de la comprobación compartida (automática al iniciar sesión o manual). Sin porcentajes inventados.
