// Preferencias de avisos de correo, propias de cada usuario en este navegador. Los sonidos vienen desactivados.
const mailPrefsKey=()=>'ordenes-pro:mail-prefs:'+(currentUser?.username||'');
function mailPrefs(){const prefs={received:false,sent:false,error:false,volume:.6,mute:false,popups:true,desktop:false,custom:false};try{Object.assign(prefs,JSON.parse(localStorage.getItem(mailPrefsKey())||'{}'));}catch{}return prefs;}
function saveMailPrefs(prefs){try{localStorage.setItem(mailPrefsKey(),JSON.stringify(prefs));}catch{}clearTimeout(saveMailPrefs.timer);saveMailPrefs.timer=setTimeout(()=>{api('/api/mail/prefs',{prefs:JSON.stringify(prefs)}).catch(()=>{});},600);}
// Las preferencias se guardan en la cuenta: al iniciar sesión en otro equipo se aplican las del servidor (el archivo de audio propio es local).
function adoptMailPrefs(){if(!currentUser?.mail_prefs)return;try{const local=JSON.parse(localStorage.getItem(mailPrefsKey())||'{}');localStorage.setItem(mailPrefsKey(),JSON.stringify({...local,...currentUser.mail_prefs,custom:!!local.custom}));}catch{}}
let mailAudio=null,mailCustom=null;
// Sonidos de correo. «received» es un timbre clásico de cuatro notas creado para Órdenes Pro (no es el audio de Windows XP); si la persona cargó un archivo propio con licencia, se usa ese.
async function mailSound(type,force=false){
 const prefs=mailPrefs();if(!force&&(prefs.mute||!prefs[type]))return false;if(navigator.userActivation&&!navigator.userActivation.hasBeenActive)return false;
 try{mailAudio=mailAudio||new (window.AudioContext||window.webkitAudioContext)();if(mailAudio.state==='suspended')await Promise.race([mailAudio.resume(),new Promise(resolve=>setTimeout(resolve,900))]);if(mailAudio.state!=='running')return false;const now=mailAudio.currentTime,volume=Math.max(0,Math.min(1,+prefs.volume||0));if(!volume)return false;
  if(type==='received'&&prefs.custom){try{const stored=localStorage.getItem(mailPrefsKey()+':audio')||'';if(stored){if(!mailCustom||mailCustom.source!==stored){const bytes=Uint8Array.from(atob(stored),char=>char.charCodeAt(0));mailCustom={source:stored,buffer:await mailAudio.decodeAudioData(bytes.buffer)};}const player=mailAudio.createBufferSource(),gain=mailAudio.createGain();player.buffer=mailCustom.buffer;gain.gain.value=volume;player.connect(gain);gain.connect(mailAudio.destination);player.start();return true;}}catch{}}
  const notes={received:[[659.25,0,.2],[830.61,.14,.2],[987.77,.28,.22],[1318.5,.44,.5]],sent:[[587.33,0,.12],[880,.1,.22]],error:[[233.08,0,.22],[174.61,.2,.32]]}[type];if(!notes)return false;
  for(const[frequency,at,length]of notes)for(const[kind,level]of [['sine',.2],['triangle',.07]]){const osc=mailAudio.createOscillator(),gain=mailAudio.createGain();osc.type=kind;osc.frequency.value=frequency;gain.gain.setValueAtTime(.0001,now+at);gain.gain.linearRampToValueAtTime(level*volume,now+at+.012);gain.gain.exponentialRampToValueAtTime(.0001,now+at+length);osc.connect(gain);gain.connect(mailAudio.destination);osc.start(now+at);osc.stop(now+at+length+.04);}
  return true;}catch{return false;}
}
function mailSize(bytes){const unit=(value,name)=>(value>=100?String(Math.round(value)):value.toFixed(1).replace('.',',').replace(',0',''))+' '+name,mb=bytes/1048576;return mb>=999.5?unit(bytes/1073741824,'GB'):mb>=1?unit(mb,'MB'):Math.max(1,Math.round(bytes/1024))+' KB';}
// Ajusta la altura de un módulo de pantalla completa al espacio visible real (zoom, barras y contenedor con desplazamiento propio).
function fitToViewport(node,property,minimum){
 const view=window.visualViewport,stop=new AbortController();
 function fit(){if(!node.isConnected){stop.abort();return;}const height=view?.height||innerHeight;let scroller=node.parentElement;while(scroller&&scroller!==document.body&&!/(auto|scroll)/.test(getComputedStyle(scroller).overflowY))scroller=scroller.parentElement;let space,offset;if(!scroller||scroller===document.body){space=height;offset=node.getBoundingClientRect().top+scrollY;}else{const box=scroller.getBoundingClientRect();space=Math.min(height,box.bottom)-Math.max(0,box.top);offset=node.getBoundingClientRect().top-box.top+scroller.scrollTop;}node.style.setProperty(property,Math.floor(Math.max(Math.min(minimum,space-12),space-offset-14))+'px');}
 fit();addEventListener('resize',fit,{signal:stop.signal});view?.addEventListener('resize',fit,{signal:stop.signal});return fit;
}
