// e informes de rebote o demora que llegan al buzón: no se muestra «Entregado» sin un informe real ni se registran aperturas.
const deliveryIcons={cola:'M12 6v6l4 2 M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20z',enviando:'M21 12a9 9 0 1 1-6.22-8.56',enviado:'M22 2 11 13 M22 2l-7 20-4-9-9-4z',entregado:'M18 6 7 17l-5-5 M22 10l-7.5 7.5L13 16',demorado:'M12 8v4l2 2 M10.3 3.9 1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0z',rebotado:'M9 14 4 9l5-5 M4 9h10.5a5.5 5.5 0 0 1 0 11H11',fallido:'M18 6 6 18 M6 6l12 12',abierto:'M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7z M12 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6z',desconocido:'M9.1 9a3 3 0 0 1 5.8 1c0 2-3 3-3 3 M12 17h.01 M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20z'};
