 const stageOf=text=>/Autenticando/.test(text||'')?'autenticado':/Transmitiendo/.test(text||'')?'aceptado':/Conectando/.test(text||'')?'conectando':'resultado';
 // Etapa donde se rompió el envío: rechazo o falta de confirmación del servidor → «Aceptado por servidor»; rebote posterior → «Resultado final».
 let broken='';if(!['enviado','entregado','demorado'].includes(d.status)){if(d.status==='rebotado'&&seen.has('aceptado'))broken='resultado';else if(fail)broken=['rechazo','rechazo_temporal','sin_confirmacion','sin_respuesta'].includes(fail.event)?'aceptado':stageOf(fail.detail);else if(d.status==='desconocido')broken='aceptado';}
