const deliveryEventNames={creado:'Mensaje creado',cola:'En cola de salida',conectando:'Conectando con el servidor SMTP',autenticado:'Autenticado',transmitiendo:'Transmitiendo el mensaje',error_etapa:'Error en una etapa del envío',resultado:'Resultado final',sin_confirmacion:'Sin confirmación del servidor SMTP',aceptado:'Aceptado por el servidor SMTP',rechazo:'Rechazado por el servidor',rechazo_temporal:'Rechazo temporal del servidor',error_envio:'Error de envío',rebote:'Informe de rebote recibido',demora:'Informe de demora recibido',entregado:'Entrega confirmada por el servidor destinatario',sin_respuesta:'Sin respuesta registrada',reenvio:'Reenvío a otra dirección'};
