// Editor de correo: el formato se guarda como marcas simples (**negrita**, _cursiva_, «- » lista) y el HTML final lo compone el servidor, nunca el navegador.
function mailEditorFill(root,text){
 root.replaceChildren();let list=null;const inline=(target,line)=>{let last=0;for(const match of line.matchAll(/\*\*(\S(?:.*?\S)?)\*\*|(?<![\w/])_(\S(?:.*?\S)?)_(?!\w)/g)){target.append(line.slice(last,match.index),el(match[1]!==undefined?'strong':'em',match[1]!==undefined?match[1]:match[2]));last=match.index+match[0].length;}target.append(line.slice(last));};
 for(const line of String(text||'').replace(/\r/g,'').split('\n')){const item=line.match(/^\s*- (.+)/);if(item){if(!list){list=el('ul');root.append(list);}const li=el('li');inline(li,item[1]);list.append(li);continue;}list=null;const row=el('div');if(line)inline(row,line);else row.append(el('br'));root.append(row);}
}
function mailEditorText(root){
 let out='';const walk=node=>{for(const child of node.childNodes){if(child.nodeType===3){out+=child.textContent.replace(/ /g,' ');continue;}if(child.nodeType!==1)continue;const tag=child.tagName;if(tag==='BR'){out+='\n';continue;}
   if(tag==='UL'||tag==='OL'){if(out&&!out.endsWith('\n'))out+='\n';for(const item of child.children){out+='- ';walk(item);if(!out.endsWith('\n'))out+='\n';}continue;}
   const block=/^(DIV|P|LI|BLOCKQUOTE|H[1-6])$/.test(tag),bold=/^(B|STRONG)$/.test(tag)||child.style?.fontWeight==='bold'||+child.style?.fontWeight>=600,italic=/^(I|EM)$/.test(tag)||child.style?.fontStyle==='italic';if(block&&out&&!out.endsWith('\n'))out+='\n';
   if(bold||italic){const start=out.length;walk(child);const inner=out.slice(start),parts=inner.match(/^(\s*)([\s\S]*?)(\s*)$/),mark=bold?'**':'_';out=out.slice(0,start)+(parts[2]?parts[1]+mark+parts[2]+mark+parts[3]:inner);}else walk(child);
   if(block&&!out.endsWith('\n'))out+='\n';}};
 walk(root);return out.replace(/\n+$/,'');
}
