function mailContactRow(row,pick){const item=button('',()=>pick(row),'rcpt-option'),avatar=el('span',((row.name||row.email||'?').trim()[0]||'?').toUpperCase(),'rcpt-avatar'),text=el('span',undefined,'rcpt-text');avatar.setAttribute('aria-hidden','true');text.append(el('strong',row.name||row.email),el('small',row.email?row.email+(row.trade_name?' · '+row.trade_name:''):'Sin correo registrado'+(row.trade_name?' · '+row.trade_name:'')));item.append(avatar,text);item.setAttribute('role','option');if(!row.email){item.classList.add('rcpt-missing');item.setAttribute('aria-disabled','true');}else item.append(systemIcon('M5 12h14 M12 5v14'));return item;}
