 const label=order.closest('label'),caption=label.querySelector('span'),pick=el('select'),hint=el('small','','mail-order-hint'),box=el('div',undefined,'mail-order-box');let auto=false,version=0,timer;
 label.classList.add('mail-order');caption.prepend(systemIcon('M9 17H7A5 5 0 0 1 7 7h2 M15 7h2a5 5 0 1 1 0 10h-2 M8 12h8'));pick.hidden=true;pick.setAttribute('aria-label','Orden en curso del cliente');hint.setAttribute('role','status');order.before(box);box.append(order,pick,hint);order.setAttribute('aria-describedby',hint.id='mail-order-hint-'+Math.random().toString(36).slice(2,8));
 const say=(text,state)=>{hint.textContent=text;hint.dataset.state=state||'';hint.hidden=!text;},describe=row=>[row.code,[row.brand,row.model].filter(Boolean).join(' '),statusNames[row.status]||row.status].filter(Boolean).join(' · ');
 const clearAuto=()=>{if(auto){order.value='';auto=false;}pick.hidden=true;pick.replaceChildren();order.hidden=false;};
 order.addEventListener('input',()=>{auto=false;if(!pick.hidden){pick.hidden=true;}say('','');});
