function identificationTypeChanged(){const kind=$('order-document_type').value,ruc=kind==='ruc',passport=kind==='pasaporte',input=$('order-identification');input.placeholder=passport?'Número de pasaporte':(ruc?'13':'10')+' dígitos';$('order-trade_name').closest('.reception-field').hidden=!ruc;const label=document.querySelector('label[for=order-client] span');const clientType=$('client-form')?.elements.client_type;if(clientType){const company=clientType.value==='empresa';$('order-document_type').querySelectorAll('option').forEach(o=>o.disabled=company&&o.value!=='ruc');}label.replaceChildren(document.createTextNode(ruc?'Nombres o razón social ':'Nombres y Apellidos '),el('span','*','required-mark'));identificationFeedback();}
function validateReception(data,step=null){const form=$('order-form'),errors={};for(const input of form.querySelectorAll('input,select,textarea')){if(step!==null&&+input.closest('[data-step]')?.dataset.step!==step)continue;if(input.required&&!['radio','checkbox'].includes(input.type)&&!input.value.trim())errors[input.name]='Completa este campo.';if(input.maxLength>0&&input.value.length>input.maxLength)errors[input.name]='Texto demasiado largo.';}if((step===null||step===0)&&(!selectedClient||String(selectedClient.id)!==data.client_id))errors.client_id='Busca y selecciona un cliente registrado.';if((step===null||step===1)&&data.serial&&!/^[A-Za-z0-9-]+$/.test(data.serial))errors.serial='Utiliza letras, números y guiones.';if(step===null||step===2)Object.assign(errors,accessErrors(accessPayload(form)));if(step===null||step===WIZARD_LAST){if(!termsReady)errors.terms_accept='Espera la carga de condiciones o reintenta.';else if(termsRequired&&!currentTerms)errors.terms_accept='Esta instalación exige condiciones publicadas y todavía no hay ninguna vigente.';else if(currentTerms&&!form.elements.terms_accept.checked)errors.terms_accept='Registra la aceptación de esta versión.';}return errors;}
