let wizardPaintQueued=false;function queueWizardStepper(){if(wizardPaintQueued)return;wizardPaintQueued=true;requestAnimationFrame(()=>{wizardPaintQueued=false;paintWizardStepper();});}
function showWizardStep(step,focus=true){const changed=wizardStep!==step;wizardStep=step;const form=$('order-form');if(changed)message(form,'');form.querySelectorAll('[data-step]').forEach(panel=>panel.hidden=+panel.dataset.step!==step);form.querySelectorAll('[data-goto-step]').forEach(b=>{const n=+b.dataset.gotoStep;b.disabled=n>wizardVisited;if(n===step)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});$('wizard-back').disabled=step===0;$('wizard-next').hidden=step===WIZARD_LAST;form.querySelector('.submit').hidden=step!==WIZARD_LAST;$('wizard-progress').textContent='Paso '+(step+1)+' de '+(WIZARD_LAST+1);const track=$('wizard-track');if(track)track.setAttribute('aria-valuenow',String(step+1));form.dataset.step=String(step);paintWizardStepper();paintOrderDraftNotice();updateClientSelection();if(step===2&&$('reception-clock'))$('reception-clock').textContent='Referencia de recepción: '+formatOrderDate(Date.now()+clockOffset)+' · Estado inicial: En espera. La hora definitiva se registra al guardar.';paintEquipmentMode();if(step===WIZARD_LAST)renderOrderSummary();form.querySelector('.reception-scroll').scrollTop=0;if(focus)$('wizard-heading-'+step).focus();if(step===1&&form.dataset.catalogReady!=='true')ensureEquipmentCatalog();}
