function normalizeGeo(value){return value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es').trim();}
function populateGeo(level){const list=$('geo-'+level);list.replaceChildren();for(const row of geoState[level]){const option=el('option');option.value=level==='localities'?row.name:row.name+' · '+row.code;option.label=row.kind?row.kind:'';list.append(option);}}
function clearGeoBelow(index){for(let j=index+1;j<3;j++){const level=geoLevels[j],name=geoFields[j];geoVersions[level]=(geoVersions[level]||0)+1;geoState[level]=[];operationStatus('geo-status-'+level,'');$( 'order-'+name).value='';$('order-'+name+'_code').value='';$('order-'+name).disabled=true;populateGeo(level);}$('order-city').value='';$('order-city').disabled=true;$('order-locality_code').value='';geoVersions.localities=(geoVersions.localities||0)+1;geoState.localities=[];operationStatus('geo-status-localities','');populateGeo('localities');}
const geoCache=new Map(),geoPending=new Map();
async function fetchGeo(level){
 const version=(geoVersions[level]||0)+1;geoVersions[level]=version;
 const params=new URLSearchParams({province:$('order-province_code').value,canton:$('order-canton_code').value,parish:$('order-parish_code').value});
 const key=level+'?'+params;const statusId='geo-status-'+level;operationStatus(statusId,'Cargando '+({provinces:'provincias',cantons:'cantones',parishes:'parroquias',localities:'localidades'}[level])+'…');
 try{let rows;if(geoCache.has(key))rows=geoCache.get(key);else{if(!geoPending.has(key))geoPending.set(key,api('/api/geo/'+key).then(data=>{if(!Array.isArray(data.rows))throw new Error('El servidor devuelve una ubicación incompatible.');geoCache.set(key,data.rows);return data.rows;}).finally(()=>geoPending.delete(key)));rows=await geoPending.get(key);}
 if(version!==geoVersions[level])return;geoState[level]=rows;populateGeo(level);operationStatus(statusId,'');
 if(level==='localities'){$('order-city').disabled=false;return;}const name=geoFields[geoLevels.indexOf(level)];$('order-'+name).disabled=false;
 }catch(error){if(version===geoVersions[level]){operationStatus(statusId,'No se pudo cargar la ubicación. '+catalogError(error),()=>fetchGeo(level));if(level==='localities')$('order-city').disabled=false;}}
}

async function acceptGeo(index){const name=geoFields[index],input=$('order-'+name),code=$('order-'+name+'_code'),level=geoLevels[index];const matches=geoState[level].filter(row=>normalizeGeo(input.value)===normalizeGeo(row.name+' · '+row.code)||normalizeGeo(input.value)===normalizeGeo(row.name));const row=matches.length===1?matches[0]:null;const next=row?.code||'';if(next===code.value)return;code.value=next;clearGeoBelow(index);if(row){input.value=row.name+' · '+row.code;input.removeAttribute('aria-invalid');$('error-'+name).textContent='';await fetchGeo(index<2?geoLevels[index+1]:'localities');}}
