 dialog.dataset.enhanced='true';heading.id='confirm-mac-text-title';dialog.setAttribute('aria-labelledby',heading.id);input.type='text';input.maxLength=limit;input.value=value;input.autocomplete='off';save.type='submit';field.append(el('span',label),input);actions.append(save,button('Cancelar',()=>dialog.close(),'secondary'));form.append(heading,field,actions);dialog.append(form);document.body.append(dialog);
 form.addEventListener('submit',event=>{event.preventDefault();if(!input.value.trim()){input.focus();return;}answer=input.value.trim();dialog.close();});dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close();});
