  if(diff.identical)head.append(document.createTextNode(' · sin diferencias'));else for(const[key,one,many]of [['changed','párrafo modificado','párrafos modificados'],['added','añadido','añadidos'],['removed','retirado','retirados']])if(stats[key]){const tag=el('span',stats[key]+' '+(stats[key]===1?one:many));tag.dataset.kind=key;head.append(tag);}
  box.append(head);if(diff.identical)return box;
