  const full=field(form,'Condiciones completas (sistema y PDF A4)','full_text',base.full_text,{required:true,textarea:true,maxLength:60000}),compact=field(form,'Condiciones compactas (ticket térmico)','compact_text',base.compact_text,{required:true,textarea:true,maxLength:6000}),note=field(form,'Motivo del cambio (se guarda en el historial)','note',draft?draft.note:'',{maxLength:500});full.rows=14;compact.rows=6;
  form.append(el('p','Separa los apartados con una línea vacía. Guardar el borrador o compararlo no publica nada.','settings-note'));
  const result=el('div',undefined,'terms-compare');const status=el('p','','message');status.setAttribute('role','status');
  const say=(text,ok)=>{status.textContent=text;status.dataset.ok=ok?'true':'false';};
  const body=()=>({full_text:full.value,compact_text:compact.value,note:note.value.trim()});
  const compare=button('Comparar con la versión vigente',async()=>{compare.disabled=true;try{const found=await api('/api/conditions/compare',body());result.replaceChildren(diffView(found.diff,found.current?'Cambios frente a la v'+found.current:'Texto nuevo'));if(found.compact_changed)result.append(el('p','El texto compacto del ticket también cambia.','settings-note'));say('');}catch(error){say(error.message);}finally{compare.disabled=false;}},'secondary');
  const save=button('Guardar borrador',async()=>{save.disabled=true;try{await api('/api/conditions/draft',body());toast('Borrador guardado. Queda pendiente de aprobación.','success',undefined,{title:'Condiciones'});await load();}catch(error){say(error.message);save.disabled=false;}},'secondary');
  const tools=el('div',undefined,'config-buttons terms-tools');tools.append(compare,save);
