let clockOffset=0,clockInterval=null,weatherInterval=null;
const ecuadorZone='America/Guayaquil',clockParts=new Intl.DateTimeFormat('es-EC',{timeZone:ecuadorZone,hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:true}),clockDay=new Intl.DateTimeFormat('es-EC',{timeZone:ecuadorZone,weekday:'long'}),clockDate=new Intl.DateTimeFormat('es-EC',{timeZone:ecuadorZone,day:'numeric',month:'long',year:'numeric'});
function ecuadorClockParts(milliseconds){const parts=clockParts.formatToParts(new Date(milliseconds)),get=key=>parts.find(p=>p.type===key)?.value||'';return{hour:get('hour'),minute:get('minute'),second:get('second'),period:/p/i.test(get('dayPeriod'))?'p. m.':'a. m.'};}
