    for(const row of data.rows){const item=make('details',undefined,'version-entry'),summary=make('summary'),line=make('span');line.append(make('strong','v'+row.version),make('small',[day(row.date),row.type].filter(Boolean).join(' · ')));summary.append(line,make('span',row.summary||'Sin resumen','version-entry-summary'));item.append(summary);const inner=make('div',undefined,'version-entry-notes');if(row.notes.length)notesOf(inner,row.notes);else inner.append(make('p','Sin notas detalladas.','version-news-summary'));item.append(inner);if(row.version===info.version)item.dataset.current='true';more.before(item);}
