function orderSection(title,entries){const section=el('section',undefined,'workspace-section'),heading=el('h2',title);if(orderSectionGlyphs[title])heading.prepend(systemIcon(agendaGlyphs[orderSectionGlyphs[title]]));section.append(heading);const dl=el('dl',undefined,'workspace-fields');for(const[label,value]of entries){const group=el('div'),dd=el('dd',value||'No registrado');if(!value)dd.classList.add('is-empty');group.append(el('dt',label),dd);dl.append(group);}section.append(dl);return section;}
// Comprobante de recepción por correo: el servidor genera el PDF (con las Políticas de Reparaciones) y lo envía por SMTP.
// «Enviado» significa que el servidor de correo aceptó el mensaje; no acredita que el cliente lo haya recibido o leído.
function receiptMailToast(id,data){if(!data)return;if(data.result==='sent')toast(data.message,'success',undefined,{title:'Comprobante por correo'});else if(data.result==='failed')toast(data.message,'warning',{label:'Ver orden',run:()=>go('orders',new URLSearchParams({id:String(id)}))},{title:'Comprobante por correo'});else if(data.result==='no_email'||data.result==='not_configured')toast(data.message,'info',undefined,{title:'Comprobante por correo'});}
async function sendReceiptMail(id,mode){try{const data=await api('/api/orders/'+id+'/receipt-mail',{mode});receiptMailToast(id,data);return data;}catch(error){if(mode==='manual')notify(error.message);return null;}}
function orderReceiptMailSection(order){
 const section=el('section',undefined,'workspace-section order-receipt-mail'),state=el('p','','order-tracking-state'),note=el('small',''),list=el('ul',undefined,'order-mail-list'),actions=el('div',undefined,'order-tracking-actions'),labels={sent:'Enviado al servidor de correo',failed:'Error de envío',no_email:'Pendiente de envío — sin correo electrónico',not_configured:'Pendiente de envío — correo del sistema sin configurar'};const log=el('details',undefined,'order-mail-log'),logTitle=el('summary','Historial de envíos');log.append(logTitle,list);section.append(el('h2','Comprobante por correo'),state,note,log,actions);
 function paint(info){const last=info.history[0];state.dataset.active=String(info.sent);state.textContent=info.sent?'Enviado al servidor de correo':last?labels[last.result]:'Pendiente de envío';note.textContent=!order.email?'El cliente no tiene correo registrado. Puedes descargar o imprimir el comprobante.':!info.configured?'El correo del sistema no está configurado en el servidor.':info.sent?'El servidor de correo aceptó el mensaje. Eso no acredita que el cliente lo haya leído.':'Se envía el PDF de recepción con las Políticas de Reparaciones a '+order.email+'.';
  log.hidden=!info.history.length;logTitle.textContent='Historial de envíos ('+info.history.length+')';list.replaceChildren();for(const item of info.history){const li=el('li');li.append(el('strong',labels[item.result]+(item.recipient?' · '+item.recipient:'')),el('small',formatOrderDate(item.created_at)+' · '+(item.mode==='auto'?'Automático':'Reenvío manual')+(item.actor?' · '+item.actor:'')+(item.result==='failed'&&item.detail?' · '+item.detail:'')));list.append(li);}
  actions.replaceChildren();const send=button(info.sent?'Reenviar comprobante':'Enviar comprobante por correo',async()=>{if(info.sent&&await confirmClose({title:'¿Reenviar el comprobante?',text:'Ya se envió una vez a '+order.email+'. Se enviará de nuevo el mismo comprobante.',keep:'No reenviar',discard:'Reenviar comprobante'})!=='discard')return;send.disabled=true;send.dataset.loading='true';state.textContent='En proceso…';const data=await sendReceiptMail(order.id,'manual');send.disabled=false;if(data?.receipt_mail)paint(data.receipt_mail);},'secondary');send.disabled=!order.email||!info.configured;actions.append(send);const pdf=el('a','Descargar PDF','secondary');pdf.href='/api/orders/'+order.id+'/receipt.pdf';pdf.target='_blank';pdf.rel='noopener';actions.append(pdf);}
 paint(order.receipt_mail);return section;
}
