// «Gestión técnica del equipo» (antes «Editar orden»): estado, responsable, prioridad, entrega e informes de UN equipo. Cada equipo de una
// orden es un ingreso propio (id), así que guardar aquí nunca toca los demás equipos de la misma orden.
// Movimientos de la orden para la línea de tiempo: el tipo se deduce del evento registrado y, cuando lo indica, de su comentario.
// No se inventa nada: título, detalle, fecha y responsable salen del historial; un correo «enviado» no se presenta como entregado.
const orderEventLooks={recepcion:['violeta','M9 2h6a1 1 0 0 1 1 1v2H8V3a1 1 0 0 1 1-1z M8 4H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V6a2 2 0 0 0-2-2h-2 M9 12h6 M9 16h4'],comprobante:['verde','M4 5h16a1 1 0 0 1 1 1v6 M3 7l9 6 9-6 M3 7v11a1 1 0 0 0 1 1h8 M16 19l2 2 4-4'],aviso:['azul','M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9 M10.3 21a1.94 1.94 0 0 0 3.4 0'],tecnica:['celeste','M14.7 6.3a4 4 0 0 0-5.4 5.4L3 18l3 3 6.3-6.3a4 4 0 0 0 5.4-5.4l-2.6 2.6-2.4-2.4z'],
 presupuesto:['ambar','M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 13h8 M8 17h5'],aprobacion:['verde','M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M9 12l2 2 4-4'],cancelacion:['rojo','M4.9 4.9l14.2 14.2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'],mantenimiento:['turquesa','M8 2v4 M16 2v4 M3 10h18 M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2z'],estado:['azul','M12 8v4l3 2 M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20z']};
function orderActivity(history){const now=Date.now()+clockOffset;return history.map((row,index)=>{const info=activityInfo(row),text=row.comment||'';
  const kind=row.event==='created'?'recepcion':row.event==='maintenance'?'mantenimiento':/cancel|anul/i.test(text)?'cancelacion':/^presupuesto/i.test(text)?(/aprobad/i.test(text)&&!/rechaz/i.test(text)?'aprobacion':'presupuesto'):/comprobante/i.test(text)?'comprobante':/aviso|autorizaci[oó]n/i.test(text)?'aviso':info.kind.group==='status'?'estado':'tecnica',look=orderEventLooks[kind];
  return{tone:look[0],glyph:look[1],title:kind==='recepcion'?'Recepción registrada':info.title,when:row.occurred_at,actor:info.actor,detail:[info.detail,info.comment].filter(Boolean).join(' — '),fresh:index===0&&now-new Date(row.occurred_at).getTime()<90000};});}
