// más «consultando» y «no disponible», para no mostrar como definitivo —ni como cero— un saldo que no se pudo leer.
const financeGlyphs={pendiente:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20z M12 8v4 M12 16h.01',parcial:'M19 7V4a1 1 0 0 0-1-1H5a2 2 0 0 0 0 4h15a1 1 0 0 1 1 1v4h-3a2 2 0 0 0 0 4h3a1 1 0 0 0 1-1v-2a1 1 0 0 0-1-1 M3 5v14a2 2 0 0 0 2 2h15a1 1 0 0 0 1-1v-4',pagado:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20z M9 12l2 2 4-4',sin_cargos:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M9 15h6',credito:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20z M12 8v8 M8 12h8',loading:'M21 12a9 9 0 1 1-6.2-8.6',unavailable:'M12 9v4 M12 17h.01 M10.3 3.9 1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0z'};
function financialBalanceCard(summary,{scope=''}={}){const card=el('article',undefined,'finance-card'),head=el('div',undefined,'finance-card-head'),mark=el('span',undefined,'finance-card-icon'),titles=el('div'),title=el('h3','Saldo pendiente'),where=el('small',scope,'finance-card-scope'),amount=el('strong',undefined,'finance-card-amount'),state=el('p',undefined,'finance-card-state'),extra=el('p',undefined,'finance-card-extra');
 titles.append(title,where);head.append(mark,titles);card.append(head,amount,state,extra);card.setAttribute('role','group');
 const set=(code,titleText,amountText,stateText,extraText)=>{card.dataset.state=code;card.removeAttribute('aria-busy');mark.replaceChildren(systemIcon(financeGlyphs[code]));title.textContent=titleText;amount.textContent=amountText;state.textContent=stateText;extra.replaceChildren();if(extraText)extra.append(extraText);extra.hidden=!extraText;card.setAttribute('aria-label',[titleText,scope,amountText,stateText].filter(Boolean).join('. '));};
 card.paint=m=>{if(!m||!m.state||!Number.isInteger(m.balance_cents)){card.unavailable();return;}const credit=m.state==='credito';
  set(m.state,credit?'Saldo a favor':'Saldo pendiente',m.state==='sin_cargos'?'—':equipmentMoney(credit?m.credit_cents:m.balance_cents),m.state_label,m.state==='sin_cargos'?'Todavía no hay cargos ni presupuestos aprobados.':credit?'Pagado '+equipmentMoney(m.paid_cents)+' sobre un total de '+equipmentMoney(m.budget_cents)+'. Registra la devolución o un nuevo cargo.':'Pagado '+equipmentMoney(m.paid_cents)+' de '+equipmentMoney(m.budget_cents)+'.');};
 card.loading=()=>{set('loading','Saldo pendiente','···','Consultando el saldo…','');card.setAttribute('aria-busy','true');};
 card.unavailable=retry=>{set('unavailable','Saldo pendiente','—','Saldo no disponible',retry?button('Reintentar',retry,'text-action'):'No se pudo consultar. Recarga la orden para verlo.');};
 card.paint(summary);return card;}
// Tras un pago, anulación, devolución o asignación: las tarjetas pasan a «consultando», se vuelve a leer la orden y se repinta el
// detalle sin perder la posición. Si la lectura falla, las tarjetas dicen «Saldo no disponible» (nunca cero) y ofrecen reintentar.
async function refreshOrderFinance(id){const cards=[...document.querySelectorAll('.finance-card')];cards.forEach(card=>card.loading());
 try{const{order}=await api('/api/orders/'+id);const root=$('module-content'),y=scrollY;if(!root.querySelector('.finance-card'))return;renderOrderDetail(root,order);scrollTo(0,y);}
 catch{cards.forEach(card=>{if(card.isConnected)card.unavailable(()=>refreshOrderFinance(id));});}}
const financeKey=()=>(crypto.randomUUID?crypto.randomUUID():'k'+Date.now().toString(36)+Math.random().toString(36).slice(2)+Math.random().toString(36).slice(2)).slice(0,60);
function paymentsSection(order){const section=el('section',undefined,'workspace-section equip-pay'),title=el('h2','Pagos y saldo'),m=order.money,group=order.group||{},multiple=!!group.multiple,whole=group.totals||m,delivered=order.status==='entregado',unitName=multiple?(order.unit_code||'').split('-').pop():'';title.prepend(systemIcon('M3 6h18v12H3z M3 10h18 M7 15h3'));section.append(title);
 section.append(financialBalanceCard(m,{scope:multiple?'Saldo del equipo '+unitName:'Saldo de la orden'}));
 section.append(el('small',m.state==='sin_cargos'?'Sin cargos registrados: no hay saldo que cobrar.':m.state==='credito'?'El equipo tiene saldo a favor del cliente. No impide la entrega.':m.balance_cents?'El equipo no puede entregarse mientras tenga saldo pendiente.'+(whole.general_cents>0?' La orden tiene '+equipmentMoney(whole.general_cents)+' de pagos generales sin asignar.':''):'Sin saldo pendiente: el equipo puede entregarse.','equip-pay-note'));
 const moveText=pay=>(pay.kind==='devolucion'?'Devolución · − ':pay.kind==='asignacion'?'Asignado de un pago general · ':'')+equipmentMoney(pay.amount_cents)+' · '+(order.payment_methods[pay.method]||pay.method);
 const listOf=(rows,label)=>{const list=el('ul',undefined,'equip-pay-list');list.setAttribute('aria-label',label);for(const pay of rows){const li=el('li'),copy=el('span');if(pay.voided_at)li.dataset.voided='true';li.dataset.kind=pay.kind;copy.append(el('strong',moveText(pay)),el('small',[formatOrderDate(pay.created_at),pay.actor,pay.note,pay.kind==='pago'&&pay.free_cents!==undefined&&!pay.voided_at?(pay.free_cents?'Sin asignar: '+equipmentMoney(pay.free_cents):'Asignado por completo'):'',pay.voided_at?'Anulado: '+pay.void_reason:''].filter(Boolean).join(' · ')));li.append(copy);
    const acts=el('span',undefined,'equip-pay-acts');if(pay.free_cents>0&&m.balance_cents>0&&!delivered&&!pay.voided_at)acts.append(button('Asignar a '+(unitName||'este equipo'),event=>assignPayment(order,pay,event.currentTarget),'text-action'));
    // Recibo del movimiento: PDF para imprimir y envío al correo registrado del cliente (el destinatario lo decide el servidor).
    if(pay.kind!=='asignacion'){const pdf=el('a','Recibo','text-action');pdf.href='/api/orders/'+order.id+'/payments/'+pay.id+'/receipt.pdf';pdf.target='_blank';pdf.rel='noopener';pdf.setAttribute('aria-label','Abrir el recibo del movimiento de '+equipmentMoney(pay.amount_cents)+' en PDF');acts.append(pdf);
     if(!pay.voided_at){const send=button('Enviar recibo',async()=>{if(send.disabled)return;if(!await askConfirm('¿Enviar el recibo al cliente?','Se enviará por correo a '+(order.email||'la dirección registrada del cliente')+' el recibo de '+equipmentMoney(pay.amount_cents)+', con el saldo actual.','Enviar recibo'))return;send.disabled=true;try{const result=await api('/api/orders/'+order.id+'/payments/receipt-mail',{payment_id:String(pay.id)});toast(result.message,'success',undefined,{title:'Recibo enviado'});}catch(error){notify(error.message);}finally{send.disabled=false;}},'text-action');acts.append(send);}}
    if(admin()&&!pay.voided_at&&!delivered&&pay.kind!=='asignacion')acts.append(button('Anular',()=>voidPayment(order,pay),'text-action'));if(acts.childElementCount)li.append(acts);list.append(li);}return list;};
 if(order.payments.length)section.append(listOf(order.payments,'Movimientos de este equipo'));
 if(multiple&&(group.general_payments||[]).length){section.append(el('h3','Pagos generales de la orden','equip-pay-sub'),el('small','No pertenecen a un equipo hasta que se asignan. Cuentan una sola vez en el saldo general.','equip-pay-note'),listOf(group.general_payments,'Pagos generales de la orden'));}
 const canPayUnit=m.balance_cents>0&&!delivered,canPayOrder=multiple&&whole.balance_cents>0;
 if(canPayUnit||canPayOrder){const form=el('form',undefined,'equip-pay-form'),scope=el('select'),amount=el('input'),method=el('select'),note=el('input'),save=el('button','Registrar pago','primary'),status=el('p',undefined,'message');let key=financeKey();form.noValidate=true;
   scope.name='scope';scope.setAttribute('aria-label','Aplicar el pago a');if(canPayUnit)scope.append(new Option(multiple?'Aplicar a este equipo ('+unitName+')':'Este equipo','equipo'));if(canPayOrder)scope.append(new Option('Pago general de la orden (sin equipo)','general'));scope.hidden=!multiple;
   const limit=()=>scope.value==='general'?whole.balance_cents:m.balance_cents,fill=()=>{amount.value=(limit()/100).toFixed(2);};
   amount.name='amount';amount.inputMode='decimal';amount.autocomplete='off';amount.placeholder='0.00';amount.setAttribute('aria-label','Importe del pago en USD');method.name='method';method.setAttribute('aria-label','Forma de pago');for(const[code,label]of Object.entries(order.payment_methods)){const o=el('option',label);o.value=code;method.append(o);}note.name='note';note.maxLength=300;note.placeholder='Nota o referencia (opcional)';note.setAttribute('aria-label','Nota o referencia del pago');save.type='submit';status.setAttribute('role','status');fill();scope.addEventListener('change',fill);
   // Mientras no cambien los datos, un doble clic o un reintento reutilizan la misma clave: el servidor no registra el pago dos veces.
   for(const node of [scope,amount,method,note])node.addEventListener('input',()=>{key=financeKey();});
   form.append(scope,amount,method,note,save,status);form.addEventListener('submit',async event=>{event.preventDefault();if(save.disabled)return;const typed=amount.value.trim();if(!/^\d{1,7}([.,]\d{1,2})?$/.test(typed)||!(parseFloat(typed.replace(',','.'))>0)){status.textContent='Indica un importe mayor que cero con hasta dos decimales.';amount.focus();return;}
    save.disabled=true;status.textContent='';try{const result=await api('/api/orders/'+order.id+'/payments',{amount:typed,method:method.value,note:note.value.trim(),scope:scope.value,request_key:key});toast(result.duplicate?'Este pago ya estaba registrado.':'Pago registrado.','success');await refreshOrderFinance(order.id);}catch(error){status.textContent=error.message;save.disabled=false;(error.fields?.amount?amount:error.fields?.method?method:note).focus();}});section.append(form);}
 if(admin()&&!delivered&&m.paid_cents>0){const refund=button('Registrar devolución',()=>refundPayment(order),'secondary equip-pay-refund');refund.prepend(systemIcon('M3 12a9 9 0 1 0 3-6.7L3 8 M3 3v5h5'));section.append(refund);}
 if(admin())section.append(invoiceBlock(order));
 return section;}
async function assignPayment(order,pay,trigger){if(trigger.disabled)return;trigger.disabled=true;try{const result=await api('/api/orders/'+order.id+'/payments/assign',{payment_id:String(pay.id)});toast('Se asignaron '+equipmentMoney(result.amount_cents)+' a este equipo.','success');await refreshOrderFinance(order.id);}catch(error){notify(error.message);trigger.disabled=false;}}
function refundPayment(order){const dialog=smallDialog('Registrar devolución'),form=el('form',undefined,'equip-void'),amount=el('input'),method=el('select'),reason=el('textarea'),status=el('p',undefined,'message'),save=el('button','Registrar devolución','primary'),key=financeKey();form.noValidate=true;
 amount.inputMode='decimal';amount.autocomplete='off';amount.placeholder='0.00';amount.setAttribute('aria-label','Importe de la devolución en USD');if(order.money.credit_cents)amount.value=(order.money.credit_cents/100).toFixed(2);method.setAttribute('aria-label','Forma de devolución');for(const[code,label]of Object.entries(order.payment_methods))method.append(new Option(label,code));reason.rows=3;reason.maxLength=300;reason.placeholder='Motivo o referencia de la devolución';reason.setAttribute('aria-label','Motivo o referencia de la devolución');reason.dataset.adi='off';save.type='submit';status.setAttribute('role','status');
 form.append(el('p','La devolución resta de lo pagado por este equipo (hasta '+equipmentMoney(order.money.paid_cents)+') y queda en el historial. No cambia el estado técnico del equipo.'),amount,method,reason,status,save);dialog.append(form);amount.focus();
 form.addEventListener('submit',async event=>{event.preventDefault();if(save.disabled)return;save.disabled=true;status.textContent='';try{await api('/api/orders/'+order.id+'/payments',{kind:'devolucion',amount:amount.value.trim(),method:method.value,note:reason.value.trim(),request_key:key});dialog.close();toast('Devolución registrada.','success');await refreshOrderFinance(order.id);}catch(error){status.textContent=error.message;save.disabled=false;(error.fields?.amount?amount:reason).focus();}});}
function voidPayment(order,pay){const refund=pay.kind==='devolucion',dialog=smallDialog(refund?'Anular devolución':'Anular pago'),form=el('form',undefined,'equip-void'),reason=el('textarea'),status=el('p',undefined,'message'),save=el('button',refund?'Anular devolución':'Anular pago','primary');form.noValidate=true;reason.rows=3;reason.maxLength=300;reason.placeholder='Motivo de la anulación';reason.setAttribute('aria-label','Motivo de la anulación');reason.dataset.adi='off';save.type='submit';status.setAttribute('role','status');
 form.append(el('p',refund?'Se anulará la devolución de '+equipmentMoney(pay.amount_cents)+'. El registro se conserva con el motivo y el importe vuelve a contar como pagado.':'Se anulará el pago de '+equipmentMoney(pay.amount_cents)+'. El registro se conserva con el motivo y vuelve a contar como saldo pendiente.'),reason,status,save);dialog.append(form);reason.focus();
 form.addEventListener('submit',async event=>{event.preventDefault();if(save.disabled)return;save.disabled=true;try{await api('/api/orders/'+order.id+'/payments/void',{payment_id:String(pay.id),reason:reason.value.trim()});dialog.close();toast(refund?'Devolución anulada.':'Pago anulado.','success');await refreshOrderFinance(order.id);}catch(error){status.textContent=error.message;save.disabled=false;reason.focus();}});}
// Historial de correos de la orden: cada mensaje que el sistema envió, con su estado real y la copia exacta guardada al enviarlo.
// «✦ Revisado por ADI» aparece solo si ADI completó la revisión de ese mensaje; con plantilla sin intervención de la IA no se muestra.
function mailHistorySection(order){const section=el('section',undefined,'workspace-section mail-history'),title=el('h2','Historial de correos'),rows=order.mail_history||[];title.prepend(systemIcon('M4 5h16a1 1 0 0 1 1 1v12a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V6a1 1 0 0 1 1-1z M3 7l9 6 9-6'));section.append(title);
 if(!rows.length){section.append(el('p','El sistema todavía no ha enviado correos de esta orden.','system-muted'));return section;}
 const list=el('ul',undefined,'mail-history-list');for(const row of rows){const li=el('li'),copy=el('div'),meta=el('small'),state=el('span',row.status_label,'mail-history-state');li.dataset.status=row.status;state.dataset.status=row.status;if(row.status==='error')state.title=row.detail||'El servidor de correo no aceptó el mensaje';
   meta.append(document.createTextNode(formatOrderDate(row.sent_at||row.created_at)+' · '+row.recipient));copy.append(el('strong',row.subject),meta);const tags=el('div',undefined,'mail-history-tags');tags.append(state);
   if(row.adi==='revisado'){const star=el('span',undefined,'adi-reviewed');star.append(systemIcon('M12 3l1.9 5.8a2 2 0 0 0 1.3 1.3L21 12l-5.8 1.9a2 2 0 0 0-1.3 1.3L12 21l-1.9-5.8a2 2 0 0 0-1.3-1.3L3 12l5.8-1.9a2 2 0 0 0 1.3-1.3z'),el('span','Revisado por ADI'));star.title='ADI completó la revisión de este mensaje antes de enviarlo';tags.append(star);}
   li.append(copy,tags,button('Ver correo',()=>openArchivedMail(row.id),'secondary'));list.append(li);}
 section.append(list);return section;}
async function openArchivedMail(id){const dialog=smallDialog('Correo enviado'),body=el('div',undefined,'mail-archived');dialog.classList.add('mail-archived-dialog');dialog.append(body);body.append(el('p','Cargando…','system-muted'));
 try{const{mail}=await api('/api/sent-mail/'+id);body.replaceChildren();const facts=el('dl',undefined,'workspace-fields');for(const[label,value]of [['Asunto',mail.subject],['Destinatario',mail.recipient],['Orden',mail.order_code||'Sin orden asociada'],['Tipo',mail.kind_label],['Fecha y hora',formatOrderDate(mail.sent_at||mail.created_at)],['Estado',mail.status_label+(mail.status==='error'&&mail.detail?': '+mail.detail:'')],['Revisión ADI',mail.adi==='revisado'?'✦ Revisado por ADI':'Plantilla revisada previamente (sin intervención de ADI en este envío)'],...(mail.attachments?[['Adjuntos',mail.attachments]]:[])]){const box=el('div');box.append(el('dt',label),el('dd',value));facts.append(box);}
  const text=el('pre',mail.text,'mail-archived-text');text.tabIndex=0;text.setAttribute('aria-label','Texto exacto del mensaje');body.append(facts,el('small','Esta es la copia guardada en el momento del envío: no cambia aunque después cambien las plantillas. Los enlaces privados de un solo uso se omiten.','mail-archived-note'),text);
  if(mail.view_url){const open=el('a','Abrir la versión con formato','primary');open.href=mail.view_url;open.target='_blank';open.rel='noopener';body.append(open);}}
 catch(error){body.replaceChildren(el('p',error.message,'empty-module'));}}
// Presupuestos profesionales. Cada orden tiene versiones (P1, P2…) con estado por ítem; los precios incluyen IVA y el desglose lo
// calcula el servidor. Las decisiones solo cambian con acciones registradas (cliente por su enlace o administración con nota).
const quoteMoney=cents=>'$'+Math.floor((cents||0)/100).toLocaleString('es-EC')+','+String((cents||0)%100).padStart(2,'0');
const quoteGlyphs={borrador:'M12 20h9 M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4z',enviado:'M12 6v6l4 2 M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20z',revision:'M12 6v6l4 2 M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20z',sin_correo:'M4 5h16a1 1 0 0 1 1 1v6 M3 7l9 6 9-6 M3 7v11a1 1 0 0 0 1 1h9 M17 17l4 4 M21 17l-4 4',aprobado:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M9 12l2 2 4-4',parcial:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20z M12 2v20',rechazado:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M15 9l-6 6 M9 9l6 6',modificacion:'M3 12a9 9 0 0 1 15.3-6.4L21 8 M21 3v5h-5 M21 12a9 9 0 0 1-15.3 6.4L3 16 M3 21v-5h5',cancelado:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M8 12h8',pendiente:'M12 6v6l4 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'};
const catalogGlyphs={servicio:'M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z',licencia:'M15 7a4 4 0 1 0-4 4h1l2 2h2v2h2v2h3v-3l-6.3-6.3A4 4 0 0 0 15 7z M10.5 7.5h.01',seguridad:'M20 13c0 5-3.5 7.5-7.66 8.95a1 1 0 0 1-.67-.01C7.5 20.5 4 18 4 13V6a1 1 0 0 1 1-1c2 0 4.5-1.2 6.24-2.72a1.17 1.17 0 0 1 1.52 0C14.51 3.81 17 5 19 5a1 1 0 0 1 1 1z M9 12l2 2 4-4',repuesto:'M4 4h16v16H4z M9 9h6v6H9z M9 1v3 M15 1v3 M9 20v3 M15 20v3 M20 9h3 M20 14h3 M1 9h3 M1 14h3',otro:'M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z M3.3 7 12 12l8.7-5 M12 22V12'};
// Imagen del elemento: la que cargó administración; si no hay, el logotipo de su marca del catálogo central; si tampoco, un icono de su categoría.
// Iconos y clasificaciones del catálogo: los entrega el servidor (/api/catalog y el presupuesto), el mismo origen que usa el PDF.
let catalogIcons={},quotePriorities={};
const catalogIconNode=key=>systemIcon(catalogIcons[key]?.path||catalogIcons.generico?.path||catalogGlyphs.otro);
function priorityBadge(code){const info=quotePriorities[code];if(!info)return null;const badge=el('span',info.label,'quote-priority');badge.dataset.priority=code;return badge;}
function catalogLogo(item,logos,className='catalog-logo'){const box=el('span',undefined,className),generic=()=>{box.dataset.kind='icon';box.replaceChildren(item.icon&&catalogIcons[item.icon]?catalogIconNode(item.icon):systemIcon(catalogGlyphs[item.category]||catalogGlyphs.otro));},file=(logos||{})[brandSlug(item.brand||'')];
 if(!item.image&&!file){generic();return box;}const image=new Image();image.alt=item.brand?'Logotipo de '+item.brand:'';image.loading='lazy';image.decoding='async';image.onerror=generic;image.src=item.image?'/api/catalog/'+item.id+'/image?v='+encodeURIComponent(item.image):'/static/brands/'+file;box.dataset.kind='image';box.append(image);return box;}
function quoteBadge(status,label){const badge=el('span',undefined,'quote-badge');badge.dataset.status=status;badge.append(systemIcon(quoteGlyphs[status]||quoteGlyphs.pendiente),el('span',label));return badge;}
// Presupuesto en el detalle de la orden: dos paneles que no se confunden. Arriba, lo COTIZADO que espera la decisión del cliente (ámbar; azul si es
// borrador). Abajo, lo que el cliente AUTORIZÓ de verdad (verde), con lo pagado y el saldo. Nada pasa al panel inferior sin una aprobación registrada.
const quoteModuleLabels={enviado:'Esperando aprobación',parcial:'Aprobado parcialmente',modificacion:'Revisión solicitada'};
function quoteStage(quote,today){
 // Estado mostrado: nunca presenta un borrador como enviado. «En revisión» solo si consta que el cliente abrió y verificó su enlace; «Vencido» si pasó la validez sin decisión.
 if(quote.status==='enviado'){if(['failed','not_configured'].includes(quote.mail_state))return{code:'sin_correo',label:'Enlace creado · correo no enviado',note:quote.mail_state==='failed'?'El correo con el enlace no se pudo enviar: no consta como enviado. Reenvía el presupuesto o comparte el enlace por otro medio.':'El correo del sistema no está configurado: comparte el enlace por otro medio.'};if(quote.valid_until&&quote.valid_until<today)return{code:'vencido',label:'Vencido',note:'La validez terminó el '+dashboardDate(quote.valid_until)+' sin una decisión del cliente.'};if(quote.link?.verified_at)return{code:'revision',label:'En revisión',note:'El cliente abrió y verificó su enlace el '+formatOrderDate(quote.link.verified_at)+'.'};return{code:'enviado',label:'Esperando aprobación',note:'Enviado al cliente; todavía no ha respondido.'};}
 return{code:quote.status,label:quoteModuleLabels[quote.status]||quote.status_label,note:({borrador:'Borrador: todavía no se ha enviado al cliente.',modificacion:'El cliente pidió una modificación; edítalo y vuelve a enviarlo.',parcial:'El cliente autorizó solo una parte de las partidas'+(quote.count?.pendiente?'; '+quote.count.pendiente+' quedaron pendientes de decisión (se ofrecen en una nueva versión)':'')+'. Solo se ejecutan las aprobadas.'+(quote.client_note?' Observación: '+quote.client_note:''),aprobado:'El cliente autorizó todas las partidas.',rechazado:'El cliente no autorizó ninguna partida.'+(quote.client_note?' Motivo: '+quote.client_note:''),cancelado:'Presupuesto cancelado.'})[quote.status]||''};}
// Autorizaciones del cliente (1.5.202): cabecera, línea de tiempo con hechos registrados, servicios y productos por separado,
