// Comparte el PDF de las condiciones que corresponde a la orden: la versión aceptada o, si no hay ninguna publicada, el borrador (identificado como tal).
async function shareConditions(url,draft){
 const name=(draft?'BORRADOR - ':'')+'CONDICIONES DE RECEPCIÓN Y SERVICIOS.pdf';
 try{const blob=await fetchDocument(url),file=new File([blob],name,{type:'application/pdf'});if(navigator.canShare?.({files:[file]})){await navigator.share({title:draft?'Borrador de condiciones (sin vigencia)':'Condiciones de Recepción y Servicios · PC-DOCTOR S.A.',files:[file]});return;}
  const link=el('a'),object=URL.createObjectURL(blob);link.href=object;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(object),2000);notify(draft?'Se descargó el borrador (sin vigencia contractual). Este dispositivo no permite compartir archivos directamente.':'Se descargó el PDF de condiciones: adjúntalo en WhatsApp o correo desde tu dispositivo.',true);}
 catch(error){if(error.name!=='AbortError')notify(error.message);}
}
async function shareReceipt(id){
 try{const{order}=await api('/api/orders/'+id);const blob=await fetchDocument('/api/orders/'+id+'/receipt.pdf');const file=new File([blob],order.code+'-comprobante.pdf',{type:'application/pdf'});if(navigator.canShare?.({files:[file]})){await navigator.share({title:'Comprobante · '+order.code,files:[file]});}else{await showDocumentPreview(id,'receipt');notify('Descarga el PDF y adjúntalo en WhatsApp o correo desde tu dispositivo.',true);}}catch(error){if(error.name!=='AbortError')notify(error.message);}
}

