function operationEmpty(root,icon,text,action){const box=el('div',undefined,'operation-empty');box.append(operationIcon(icon),el('p',text));if(action)box.append(action);root.append(box);}
function dashboardDate(value){if(!value)return 'Sin fecha prevista';return new Intl.DateTimeFormat('es-EC',{day:'2-digit',month:'short',year:'numeric',timeZone:'America/Guayaquil'}).format(new Date(value+'T12:00:00-05:00'));}
function renderHomeDeliveries(rows){const root=$('operations-deliveries');root.replaceChildren();if(!rows.length){operationEmpty(root,'delivery','No hay entregas próximas programadas.');return;}
 for(const row of rows){const item=el('article',undefined,'home-record'),info=el('div');info.append(el('strong',row.client),el('p',[row.brand,row.model].filter(Boolean).join(' ')||'Equipo sin especificar'),el('small',row.code+' · '+dashboardDate(row.estimated_delivery)));const action=el('div',undefined,'home-record-actions');action.append(orderBadge(row.status_code,row.status,row.id),button('Ver orden',()=>go('orders',new URLSearchParams({id:row.id})),'text-action'));item.append(info,action);root.append(item);}}
// Citas de Hoy: solo las citas activas de la fecha actual (hora de Ecuador), en filas compactas que abren su detalle real.
// Se sincroniza por consulta periódica cada 30 s (no hay conexión persistente): una cita nueva tarda como máximo ese tiempo en aparecer.
const homeAppointmentsSeen=new Set();let homeAppointmentsFirst=true,homeAppointmentsTimer=null;
// Colores de estado del panel Citas de Hoy (borde lateral, icono y distintivo; nunca el fondo completo).
const homeAppointmentColors={solicitada:'#EABC6C',confirmada:'#62D4A3',presente:'#5BC5E8',reprogramada:'#A99AF2',completada:'#56CCBF',cancelada:'#F08089',no_asistio:'#91A3BA'};
// Estado en vivo del panel: página del carrusel, novedades («Nuevo» durante 60 s) y cancelaciones recientes (visibles unos 20 s).
const homeLive={page:0,pages:1,sig:null,paused:false,touched:Date.now(),timer:null,status:new Map(),fresh:new Map(),gone:new Map(),animated:new Set()};
const HOME_PAGE=3,HOME_ROTATE=8000,HOME_NEW=60000,HOME_GONE=20000;
function homePaintPage(slide){const root=$('home-appointments');if(!root)return;[...root.querySelectorAll('.live-appointment')].forEach((item,index)=>{const on=Math.floor(index/HOME_PAGE)===homeLive.page;item.hidden=!on;item.classList.toggle('live-page-in',on&&!!slide);});const label=root.querySelector('.live-pager-label');if(label)label.textContent=(homeLive.page+1)+' / '+homeLive.pages;}
// Avanza o retrocede un grupo completo: el orden cronológico se conserva y ninguna cita se salta.
function homeTurn(step){if(homeLive.pages<2)return;homeLive.page=(homeLive.page+step+homeLive.pages)%homeLive.pages;homeLive.touched=Date.now();homePaintPage(true);}
function homeRotate(){if(currentModule!=='home'){clearInterval(homeLive.timer);homeLive.timer=null;return;}const root=$('home-appointments');
 // En pausa (cursor encima, foco dentro, pestaña oculta o un diálogo abierto) el plazo de 8 s vuelve a empezar al reanudar.
 if(homeLive.pages<2||!root||root.matches(':hover')||root.contains(document.activeElement)||homeLive.paused||document.hidden||document.querySelector('dialog[open]')||matchMedia('(prefers-reduced-motion: reduce)').matches){homeLive.touched=Date.now();return;}if(Date.now()-homeLive.touched<HOME_ROTATE)return;homeTurn(1);}
function renderHomeAppointments(rows,today,upcoming){const root=$('home-appointments'),count=$('home-appointments-count'),mark=document.querySelector('.appointments-panel .panel-icon'),now=Date.now();if(!root)return;
 if(mark&&!mark.dataset.live){mark.dataset.live='true';mark.replaceChildren(systemIcon('M8 2v4 M16 2v4 M21 14V6a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h8 M3 10h18 M16 20l2 2 4-4'));}
 // Novedades y cancelaciones se deducen del cambio real de estado entre dos consultas; la primera carga no anuncia nada.
 for(const row of rows){const before=homeLive.status.get(row.id),closed=['cancelada','no_asistio'].includes(row.status);if(!homeAppointmentsFirst&&before===undefined&&!closed)homeLive.fresh.set(row.id,now+HOME_NEW);if(before!==undefined&&before!=='cancelada'&&row.status==='cancelada'){homeLive.gone.set(row.id,now+HOME_GONE);homeLive.fresh.delete(row.id);}homeLive.status.set(row.id,row.status);}
 for(const map of [homeLive.fresh,homeLive.gone])for(const[id,until]of map)if(until<=now||!rows.some(row=>row.id===id))map.delete(id);
 const active=rows.filter(row=>!['cancelada','no_asistio'].includes(row.status)),list=rows.filter(row=>active.includes(row)||row.status==='cancelada'&&homeLive.gone.has(row.id)).sort((a,b)=>a.starts_at.localeCompare(b.starts_at)||a.id-b.id);
 const sync=$('home-appointments-sync'),stamp=()=>{if(sync){sync.dataset.state='ok';sync.textContent='Actualizado · '+new Intl.DateTimeFormat('es-EC',{timeZone:'America/Guayaquil',hour:'2-digit',minute:'2-digit'}).format(new Date(Date.now()+clockOffset));}};
 const sig=JSON.stringify([list.map(row=>[row.id,row.status,row.starts_at,row.customer_name,row.service_label,row.brand,row.model,homeLive.fresh.has(row.id)]),upcoming&&!list.length?[upcoming.id,upcoming.starts_at,upcoming.customer_name]:0]);
 homeAppointmentsFirst=false;clearInterval(homeAppointmentsTimer);homeAppointmentsTimer=setInterval(()=>{if(currentModule!=='home'){clearInterval(homeAppointmentsTimer);return;}if(!document.hidden&&!document.querySelector('dialog[open]'))refreshHomeAppointments();},15000);if(!homeLive.timer)homeLive.timer=setInterval(homeRotate,1000);
 // Sin cambios reales no se repinta: no se repiten animaciones ni se interrumpe a quien está usando el panel.
 if(sig===homeLive.sig&&root.childElementCount){stamp();return;}
 homeLive.sig=sig;root.replaceChildren();delete root.dataset.all;
 if(count){count.hidden=!active.length;count.textContent=String(active.length);count.title=active.length===1?'1 cita activa hoy':active.length+' citas activas hoy';}
 if(!list.length){// Estado vacío compacto: una línea con el aviso y, si existe, la próxima cita futura (nunca como cita de hoy).
  const empty=el('div',undefined,'live-empty'),icon=el('span',undefined,'live-empty-icon'),text=el('div',undefined,'live-empty-text');icon.append(systemIcon('M8 2v4 M16 2v4 M21 14V6a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h8 M3 10h18 M16 20l2 2 4-4'));text.append(el('strong','Sin citas programadas para hoy'));
  if(upcoming){const next=button('',()=>openAgendaAppointment(upcoming.id,()=>refreshHomeAppointments()),'live-next');next.append(el('b','Próxima cita: '),el('span',appointmentDateTime(upcoming.starts_at)+' · '+upcoming.customer_name+' · '+upcoming.service_label));next.title='Abrir la cita '+upcoming.public_code;text.append(next);}else text.append(el('small','Las citas de hoy aparecerán aquí automáticamente.'));
  empty.append(icon,text,button('Nueva cita',()=>openAgendaBooking(()=>refreshHomeAppointments()),'secondary live-empty-new'));root.append(empty);}
 let arrived=false,firstNew=-1;
 list.forEach((row,index)=>{const cancelled=row.status==='cancelada',isNew=homeLive.fresh.has(row.id),color=homeAppointmentColors[row.status]||'#91A3BA',item=button('',()=>{homeLive.fresh.delete(row.id);openAgendaAppointment(row.id,()=>refreshHomeAppointments());},'home-appointment live-appointment'),time=el('time',row.starts_at.slice(11,16)),info=el('span',undefined,'live-appointment-info'),tags=el('span',undefined,'live-tags'),badge=agendaBadge(row.status),key=(cancelled?'c':'n')+row.id;
  time.dateTime=row.starts_at;item.style.setProperty('--ag',color);badge.style.setProperty('--ag',color);item.dataset.status=row.status;
  info.append(el('strong',row.customer_name),el('small',row.service_label+([row.brand,row.model].filter(Boolean).length?' · '+[row.brand,row.model].filter(Boolean).join(' '):'')));
  if(isNew){const fresh=agendaPill('nueva');fresh.classList.add('live-new');fresh.title='Cita registrada hace un momento';tags.append(fresh);if(firstNew<0)firstNew=index;}
  if(cancelled){badge.classList.add('live-cancelled-badge');badge.prepend(systemIcon(agendaActionIcons.cancel));item.classList.add('live-cancelled');}
  tags.append(badge);item.title=cancelled?'Cita cancelada · '+row.public_code:'Abrir la cita '+row.public_code;item.setAttribute('aria-label','Cita de las '+row.starts_at.slice(11,16)+', '+row.customer_name+', '+row.service_label+', '+(agendaStatus[row.status]||[row.status])[0]+(isNew?', nueva':''));
  // La animación de llegada se ejecuta una sola vez por evento.
  if((isNew||cancelled)&&!homeLive.animated.has(key)){homeLive.animated.add(key);item.classList.add('live-enter');if(isNew)arrived=true;}
  item.append(time,info,tags);root.append(item);});
 homeLive.pages=Math.max(1,Math.ceil(list.length/HOME_PAGE));if(arrived&&firstNew>=0)homeLive.page=Math.floor(firstNew/HOME_PAGE);homeLive.page=Math.min(homeLive.page,homeLive.pages-1);
 if(homeLive.pages>1){const pager=el('div',undefined,'live-pager'),prev=button('',()=>homeTurn(-1),'live-pager-button'),next=button('',()=>homeTurn(1),'live-pager-button'),label=el('span','','live-pager-label'),total=el('span',list.length+' citas','live-pager-total');prev.append(systemIcon('m15 18-6-6 6-6'));next.append(systemIcon('m9 18 6-6-6-6'));prev.setAttribute('aria-label','Citas anteriores');next.setAttribute('aria-label','Citas siguientes');prev.title='Anteriores';next.title='Siguientes';label.setAttribute('aria-label','Grupo de citas');pager.setAttribute('role','group');pager.setAttribute('aria-label','Navegación entre las citas de hoy');pager.append(prev,label,next,total);root.append(pager);}
 // Con varias páginas el alto queda fijo al de un grupo completo: el resto del inicio no salta al rotar.
 root.style.minHeight='';homeLive.page=Math.min(homeLive.page,homeLive.pages-1);if(homeLive.pages>1){const keep=homeLive.page;homeLive.page=0;homePaintPage(false);root.style.minHeight=root.offsetHeight+'px';homeLive.page=keep;}homePaintPage(false);homeLive.touched=Date.now();
 if(arrived&&mark){mark.classList.remove('tracking-pulse');void mark.offsetWidth;mark.classList.add('tracking-pulse');mark.addEventListener('animationend',()=>mark.classList.remove('tracking-pulse'),{once:true});}
 stamp();}
// Aviso de ADI cuando hoy es feriado: aparece aunque no haya citas ni órdenes. El texto lo entrega el servidor con el modo de atención vigente.
function holidayBanner(notice,className='adi-holiday'){const box=el('aside',undefined,className),mark=el('span',undefined,'adi-holiday-icon'),copy=el('div');box.setAttribute('role','status');box.dataset.mode=notice.decided?notice.mode:'sin-definir';mark.append(systemIcon('M8 2v4 M16 2v4 M3 10h18 M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2z M9 16l2 2 4-4'));copy.append(el('strong',notice.text));if(!notice.decided&&admin())copy.append(el('small','Aún no se ha definido cómo se atiende este feriado. Elige atención normal, horario especial o cerrado.'));box.append(mark,copy);
 if(admin())box.append(button(notice.decided?'Ver feriados':'Definir atención',openHolidaySettings,'secondary'));return box;}
// Abre la configuración de la agenda (plegada dentro de «Citas») y lleva al gestor de feriados.
function openHolidaySettings(){const reveal=tries=>{const panel=document.querySelector('.holiday-admin');if(!panel){if(tries>0)setTimeout(()=>reveal(tries-1),300);return;}const fold=panel.closest('details');if(fold)fold.open=true;panel.closest('.config-block')?.scrollIntoView({block:'start'});};if(currentModule!=='appointments')go('appointments');reveal(20);}
// Recordatorio previo: feriado próximo cuya atención nadie ha definido (solo administración). Desaparece al decidir.
function holidayReminder(item,className='adi-holiday adi-holiday-soon'){const box=el('aside',undefined,className),mark=el('span',undefined,'adi-holiday-icon'),copy=el('div');box.setAttribute('role','status');box.dataset.mode='sin-definir';mark.append(systemIcon('M8 2v4 M16 2v4 M3 10h18 M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2z M12 14v3 M12 19.5h.01'));copy.append(el('strong',item.text));box.append(mark,copy,button('Definir atención',openHolidaySettings,'secondary'));return box;}
function paintHolidayNotice(notice,reminders=[]){const anchor=$('operations-states');if(!anchor)return;const sign=JSON.stringify([notice?.day,notice?.text,reminders.map(item=>item.day+item.text)]),holder=anchor.parentElement,old=[...holder.querySelectorAll(':scope>.adi-holiday')];if(holder.dataset.holidaySign===sign)return;holder.dataset.holidaySign=sign;old.forEach(node=>node.remove());if(notice)anchor.before(holidayBanner(notice));for(const item of reminders)anchor.before(holidayReminder(item));}
async function refreshHomeAppointments(){const today=agendaDay(new Date(Date.now()+clockOffset)),sync=$('home-appointments-sync');try{const data=await api('/api/agenda?from='+today+'&to='+agendaShift(today,240));if(currentModule!=='home')return;paintHolidayNotice(data.holiday_notice,data.holiday_reminders||[]);
  // «Hoy» se decide con la fecha de Ecuador que guarda cada cita; las futuras solo se anuncian como próxima cita.
  const todays=data.appointments.filter(row=>row.starts_at.slice(0,10)===data.today),upcoming=data.appointments.find(row=>row.starts_at.slice(0,10)>data.today&&!['cancelada','no_asistio','completada'].includes(row.status));renderHomeAppointments(todays,data.today,upcoming);}catch{if(sync){sync.dataset.state='error';sync.textContent='No se pudo actualizar la agenda. Reintentando…';}}}
function renderHomeAssistance(data,failed){const root=$('home-live-pending'),conn=$('home-live-link');root.replaceChildren();
 // Indicador de conexión real: «En línea» con la hora de la última consulta correcta, o el aviso de que no se pudo actualizar.
 if(conn){conn.hidden=!admin();conn.dataset.state=failed?'error':'ok';conn.textContent=failed?'Sin conexión · reintentando':'En línea · '+new Intl.DateTimeFormat('es-EC',{timeZone:'America/Guayaquil',hour:'2-digit',minute:'2-digit'}).format(new Date(Date.now()+clockOffset));}
 if(!admin()){operationEmpty(root,'message','Consulta servicios, citas y seguimiento con ADI.',button('Hablar con ADI',()=>{if(!$('adi-widget').classList.contains('adi-open'))$('adi-toggle').click();},'secondary'));return;}
 if(failed&&!data){root.append(el('p','No se pudo consultar el estado de las atenciones. Se reintentará automáticamente.','assistance-note'));return;}
 const items=[['Nuevas','new_conversations','#5BC5E8','Conversaciones con ADI que el personal aún no ha visto'],['Esperan respuesta','waiting','#EABC6C','Clientes con un asesor solicitado cuyo último mensaje está sin responder'],['Transferidas por ADI','transferred','#A99AF2','Conversaciones que ADI pasó a un asesor y ya están en curso']],total=items.reduce((sum,[,key])=>sum+(Number(data?.[key])||0),0),waiting=Number(data?.waiting)||0,dot=$('home-live-dot');
 if(dot){dot.hidden=!total;dot.dataset.tone=waiting?'waiting':'new';dot.title=total?(waiting?waiting+(waiting===1?' cliente espera respuesta':' clientes esperan respuesta'):total+(total===1?' atención abierta':' atenciones abiertas')):'';}
 // Tres indicadores equilibrados; cada conversación cuenta en uno solo.
 const stats=el('div',undefined,'assistance-stats');stats.setAttribute('role','list');for(const[label,key,color,help]of items){const value=Number(data?.[key])||0,card=el('div',undefined,'assistance-stat');card.setAttribute('role','listitem');card.style.setProperty('--ag',color);card.dataset.active=String(value>0);if(key==='waiting'&&value>0)card.dataset.priority='true';card.title=help;card.setAttribute('aria-label',label+': '+value+'. '+help);card.append(el('strong',String(value)),el('span',label));if(assistanceCounts[key]!==undefined&&assistanceCounts[key]!==value)card.classList.add('assistance-stat-flash');assistanceCounts[key]=value;stats.append(card);}
 root.append(stats);
 const pending=data?.pending||[];
 if(!pending.length){const empty=el('div',undefined,'assistance-empty'),icon=el('span',undefined,'assistance-empty-icon'),text=el('div');icon.append(systemIcon('M21.801 10A10 10 0 1 1 17 3.335 M9 11l3 3L22 4'));text.append(el('strong',total?'Sin respuestas pendientes':'Sin atenciones pendientes'),el('small',total?'Las conversaciones abiertas ya tienen respuesta de un asesor.':'No hay conversaciones que requieran respuesta en este momento.'));empty.append(icon,text);root.append(empty);}
 else{const list=el('ul',undefined,'assistance-list');list.setAttribute('aria-label','Atenciones que requieren respuesta');
  for(const item of pending){const row=el('li'),open=button('',()=>go('live',new URLSearchParams({conversation:String(item.id)})),'assistance-item');open.dataset.kind=item.kind;const who=el('span',undefined,'assistance-who'),meta=el('span',undefined,'assistance-meta'),wait=relativeTime(item.waiting_since)||'';
   who.append(el('strong',item.client||('Visitante · conversación '+item.id)),el('small',[item.source,item.order_code].filter(Boolean).join(' · ')));
   meta.append(el('b',item.kind==='waiting'?'Espera respuesta':'Nueva'),el('small','Ingresó '+formatOrderDate(item.created_at)),el('small',wait?(item.kind==='waiting'?'Esperando: ':'Último mensaje: ')+wait.toLowerCase():''));
   open.append(who,meta);if(item.preview){const quote=el('q',item.preview);open.append(quote);}open.setAttribute('aria-label','Abrir la conversación de '+(item.client||'visitante '+item.id)+'. '+(item.kind==='waiting'?'Espera respuesta':'Nueva')+(wait?', '+wait:''));row.append(open);list.append(row);}
  root.append(list);}
 // Un solo acceso al panel completo (antes había dos botones que hacían lo mismo).
 const openAll=button('Abrir Centro de Atención',()=>go('live'),'primary assistance-open');openAll.prepend(systemIcon('M3 11h3a2 2 0 0 1 2 2v3a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2zm0 0a9 9 0 1 1 18 0m0 0v5a2 2 0 0 1-2 2h-1a2 2 0 0 1-2-2v-3a2 2 0 0 1 2-2z'));root.append(openAll);}
const assistanceCounts={};
// El Centro de Atenciones del inicio se actualiza solo cada 20 s (con la pestaña visible); si la consulta falla, el indicador lo dice.
let assistanceTimer=null;function watchHomeAssistance(initial){clearInterval(assistanceTimer);if(!admin())return;let last=initial,signature=JSON.stringify(initial||null);
 assistanceTimer=setInterval(async()=>{if(currentModule!=='home'||!$('home-live-pending')){clearInterval(assistanceTimer);return;}if(document.hidden)return;
  try{const fresh=await api('/api/assistance'),next=JSON.stringify(fresh);const arrived=last&&fresh.waiting>(last.waiting||0);last=fresh;if(next!==signature){signature=next;renderHomeAssistance(fresh);if(arrived)toast('Hay un cliente esperando respuesta en el Centro de Atención.','info',{label:'Abrir',run:()=>go('live')},{title:'Atención pendiente',id:'assistance-waiting'});}else{const conn=$('home-live-link');if(conn){conn.dataset.state='ok';conn.textContent='En línea · '+new Intl.DateTimeFormat('es-EC',{timeZone:'America/Guayaquil',hour:'2-digit',minute:'2-digit'}).format(new Date(Date.now()+clockOffset));}}}
  catch{const conn=$('home-live-link');if(conn){conn.dataset.state='error';conn.textContent='Sin conexión · reintentando';}}},20000);}

function renderAttention(rows,today){const root=$('operations-attention');root.replaceChildren();if(!rows.length){operationEmpty(root,'work','No hay órdenes pendientes de intervención.',button('Ver todas las órdenes',()=>go('orders'),'secondary'));return;}const wrap=el('div',undefined,'table-wrap'),table=el('table',undefined,'operations-table'),head=el('thead'),tr=el('tr');['Orden / cliente','Equipo','Estado','Actualización','Acción rápida'].forEach(t=>tr.append(el('th',t)));head.append(tr);table.append(head);const body=el('tbody');for(const row of rows){const tr=el('tr');const identity=el('td');identity.dataset.label='Orden / cliente';identity.append(button(row.code,()=>go('orders',new URLSearchParams({id:row.id})),'text-action'),el('small',row.client));const equipment=el('td',[row.brand,row.model].filter(Boolean).join(' ')||'Sin especificar');equipment.dataset.label='Equipo';const state=el('td');state.dataset.label='Estado';state.append(orderBadge(row.status_code,row.status,row.id));const updated=el('td',row.updated_at?formatOrderDate(row.updated_at):'Sin cambios');updated.dataset.label='Actualización';const action=el('td');action.dataset.label='Acción pendiente';const labels={esperando_cliente:'Solicitar respuesta',presupuesto:'Revisar aprobación',espera_entrega:'Coordinar entrega',listo:'Coordinar retiro'};action.append(el('small',row.estimated_delivery&&row.estimated_delivery<today?'Entrega estimada vencida':labels[row.status_code]||'Revisar retraso'),(()=>{const view=button('Ver orden',()=>go('orders',new URLSearchParams({id:row.id})),'row-action');view.prepend(operationIcon('eye'));return view;})());if(['esperando_cliente','presupuesto','espera_entrega','listo'].includes(row.status_code)&&row.phone){const a=el('a',undefined,'row-action icon-only');a.append(operationIcon('contact'));a.setAttribute('aria-label','Contactar por WhatsApp sobre la orden '+row.code);a.title='Contactar por WhatsApp';whatsappLink(a,row.phone,'Hola, le contactamos desde PC-DOCTOR S.A. sobre su orden '+row.code+'.');action.append(a);}tr.append(identity,equipment,state,updated,action);body.append(tr);}table.append(body);wrap.append(table);root.append(wrap);}
function ecuadorPhone(phone){return whatsappNumber(phone).number;}
// Número para wa.me: solo dígitos, con código de país y sin duplicarlo. No comprueba si el número tiene cuenta de WhatsApp (eso solo lo sabe WhatsApp).
function whatsappNumber(phone){const raw=String(phone||'').trim(),international=/^\s*(\+|00)/.test(raw);let p=raw.replace(/\D/g,'');if(!p)return{ok:false,number:'',reason:'El cliente no tiene un teléfono registrado.'};
 if(p.startsWith('00'))p=p.slice(2);if(p.startsWith('5930'))p='593'+p.slice(4);if(p.length===10&&p.startsWith('0'))p='593'+p.slice(1);else if(p.length===9&&p.startsWith('9'))p='593'+p;else if(p.length===9&&/^0[2-7]/.test(p))p='593'+p.slice(1);
 if(p.startsWith('593')){if(/^5939\d{8}$/.test(p))return{ok:true,number:p,reason:''};if(/^593[2-7]\d{7}$/.test(p))return{ok:false,number:p,reason:'El teléfono registrado parece un número fijo; WhatsApp necesita un celular.'};return{ok:false,number:p,reason:'El teléfono registrado está incompleto o tiene dígitos de más.'};}
 if(international&&p.length>=8&&p.length<=15)return{ok:true,number:p,reason:''};return{ok:false,number:p,reason:'El teléfono registrado no tiene un formato válido para WhatsApp.'};}
let whatsappOpenedAt=0;
// Abre la conversación con el mensaje preparado; el mensaje solo se envía cuando la persona pulsa Enviar en WhatsApp.
function openWhatsApp(phone,message){const target=whatsappNumber(phone);if(!target.ok){toast(target.reason+' Corrígelo en la ficha del cliente.','warning',undefined,{title:'WhatsApp'});return false;}if(Date.now()-whatsappOpenedAt<1500)return false;whatsappOpenedAt=Date.now();window.open('https://wa.me/'+target.number+(message?'?text='+encodeURIComponent(message):''),'_blank','noopener,noreferrer');toast('Se abrió WhatsApp con el mensaje preparado para '+'+'+target.number+'. Revisa y pulsa Enviar allí; Órdenes Pro no puede confirmar el envío.','info',undefined,{title:'WhatsApp'});return true;}
function whatsappLink(anchor,phone,message){const target=whatsappNumber(phone);anchor.href=target.ok?'https://wa.me/'+target.number+'?text='+encodeURIComponent(message):'#';anchor.target='_blank';anchor.rel='noopener noreferrer';if(!target.ok)anchor.title=target.reason;anchor.addEventListener('click',event=>{event.preventDefault();openWhatsApp(phone,message);});}
// Mensajes de WhatsApp de una orden: se rellenan con los datos reales y se pueden editar antes de abrir la conversación.
const whatsappTemplates=[['Recepción del equipo',o=>'Hola '+o.client+', le saludamos de PC-DOCTOR S.A. Recibimos su '+o.device+' con la orden '+o.code+'.'+o.track],['Diagnóstico técnico',o=>'Hola '+o.client+', ya tenemos el diagnóstico de su '+o.device+' (orden '+o.code+'): '+(o.findings||'[escriba aquí el diagnóstico]')+'.'],['Presupuesto',o=>'Hola '+o.client+', el presupuesto para su '+o.device+' (orden '+o.code+') es de '+(o.total||'[valor]')+'. Quedamos atentos a su aprobación.'],['Autorización de reparación',o=>'Hola '+o.client+', necesitamos su autorización para continuar con la reparación de su '+o.device+' (orden '+o.code+'). ¿Nos confirma por este medio?'],['Equipo listo para retirar',o=>'Hola '+o.client+', su '+o.device+' (orden '+o.code+') está listo para retirar en PC-DOCTOR S.A. Por favor presente su comprobante.'],['Recordatorio de pago',o=>'Hola '+o.client+', le recordamos el valor pendiente de la orden '+o.code+(o.total?': '+o.total:'')+'. Gracias por su atención.'],['Seguimiento de la orden',o=>'Hola '+o.client+', su orden '+o.code+' se encuentra en estado: '+o.status+'.'+o.track]];
function prepareWhatsApp(order){const dialog=smallDialog('Mensaje de WhatsApp · '+order.code),form=el('form',undefined,'whatsapp-form');dialog.classList.add('agenda-dialog');form.noValidate=true;const target=whatsappNumber(order.phone),money=cents=>new Intl.NumberFormat('es-EC',{style:'currency',currency:'USD'}).format(cents/100);
 const data={client:order.client||'cliente',code:order.code,device:[order.brand,order.model].filter(Boolean).join(' ')||'equipo',status:statusNames[order.status]||order.status,findings:(order.findings||'').trim(),total:order.budget?.total_cents?money(order.budget.total_cents):'',track:order.tracking?.url?' Puede consultar el avance aquí: '+order.tracking.url:''};
 const to=el('p','','agenda-hint');to.textContent=target.ok?'Para: '+order.client+' · +'+target.number:target.reason+' Corrígelo en la ficha del cliente para poder escribirle.';to.dataset.state=target.ok?'ok':'error';const pick=field(form,'Tipo de mensaje','template','',{select:true});whatsappTemplates.forEach(([name],index)=>pick.add(new Option(name,String(index))));const text=field(form,'Mensaje','message','',{textarea:true,maxLength:1500});text.rows=6;const fill=()=>{text.value=whatsappTemplates[+pick.value][1](data);};pick.onchange=fill;fill();
 const bar=el('div',undefined,'agenda-actions'),send=el('button','Abrir WhatsApp','primary');send.type='submit';send.disabled=!target.ok;bar.append(button('Cancelar',()=>dialog.close(),'secondary'));if(!target.ok&&order.client_id)bar.append(button('Abrir ficha del cliente',()=>{dialog.close();showClientDetail(order.client_id);},'secondary'));bar.append(send);form.prepend(to);form.append(el('p','El mensaje se abre en WhatsApp para que lo revises y lo envíes tú. El sistema no puede saber si el número tiene WhatsApp ni si el mensaje se envió.','agenda-hint'),bar);
 form.onsubmit=event=>{event.preventDefault();if(!text.value.trim()){text.focus();return;}if(openWhatsApp(order.phone,text.value.trim()))dialog.close();};dialog.append(form);text.focus();}

function relativeTime(value){const date=new Date(value),minutes=Math.round((Date.now()+clockOffset-date.getTime())/60000);if(Number.isNaN(date.getTime())||minutes<0)return '';if(minutes<1)return 'Hace un momento';if(minutes<60)return 'Hace '+minutes+' min';const hours=Math.floor(minutes/60);if(hours<24)return 'Hace '+hours+' h';const days=Math.floor(hours/24);return days===1?'Ayer':days<7?'Hace '+days+' días':'';}
