  if(/^(?:PCD-\d{8}-\d{4,}|OP-\d+)$/i.test(code)){try{const found=await api('/api/order-by-code/'+encodeURIComponent(code.toUpperCase()));close();go('orders',new URLSearchParams({id:String(found.id)}));return;}catch(error){if(error.status!==404){notify(error.message);return;}}}
