function accessPayload(form){const values=Object.fromEntries(new FormData(form)),data={};for(const name of ['technical_access','files_access','access_detail','destructive_action','destructive_detail'])if(values[name]!==undefined)data[name]=values[name];for(const name of ['access_confirmed','destructive_confirmed',...Object.keys(accessScopeLabels).map(k=>'access_'+k)])data[name]=!!form.querySelector('[name="'+name+'"]')?.checked;
 // Cada operación de riesgo viaja como dato propio; el texto que se guarda nombra además las operaciones y la unidad afectada.
 const operations=Object.entries(accessRiskLabels).filter(([key])=>form.querySelector('[name="risk_'+key+'"]')?.checked);for(const key of Object.keys(accessRiskLabels))data['risk_'+key]=operations.some(([name])=>name===key);
 data.risk_unit=values.risk_unit||'';const unit=[values.risk_unit,(values.risk_capacity||'').trim(),(values.risk_partition||'').trim()].filter(Boolean).join(', '),own=(data.destructive_detail||'').trim();data.risk_description=own;if(data.destructive_action==='authorized')data.destructive_detail=[operations.length?'Operaciones autorizadas: '+operations.map(([,text])=>text).join('; ')+'.':'',unit?'Unidad: '+unit+'.':'',own].filter(Boolean).join(' ');return data;}
function accessErrors(data){const errors={};if(!['authorized','denied'].includes(data.technical_access))errors.technical_access='Selecciona expresamente si el cliente autoriza o no el acceso.';if(!data.access_confirmed)errors.access_confirmed='Confirma que explicaste las operaciones y que la decisión del cliente quedó registrada.';if(data.technical_access==='authorized'&&!Object.keys(accessScopeLabels).some(k=>data['access_'+k]))errors.technical_access='Selecciona al menos una operación autorizada.';if((data.access_specific_files||data.access_backup)&&accessDetailWeak(data.access_detail))errors.access_detail='Describe qué carpetas, archivos o datos se pueden revisar y con qué finalidad.';if(data.files_access==='authorized'&&!data.access_specific_files&&!data.access_backup)errors.files_access='Marca qué autoriza el cliente: archivos específicos, respaldo o ambos.';
 // Modificar o eliminar datos es irreversible: se exige elegir la operación, identificar la unidad, describir lo afectado y una aceptación aparte.
 if(data.destructive_action==='authorized'){const chosen=Object.keys(accessRiskLabels).some(key=>data['risk_'+key]);if(!chosen)errors.destructive_action='Marca qué operación autoriza el cliente.';if(!data.risk_unit)errors.destructive_detail='Indica la unidad o dispositivo afectado.';else if(accessDetailWeak(data.risk_description))errors.destructive_detail='Describe con precisión qué datos o partición se verán afectados.';if(chosen&&!data.destructive_confirmed)errors.destructive_confirmed='Falta la aceptación expresa del cliente para estas operaciones.';}return errors;}
// Autorización electrónica del cliente: el personal envía un enlace seguro al correo del cliente y ve aquí el resultado real.
// El enlace solo se muestra una vez, al crearlo; después solo se conserva su huella.
function appendClientAuthorization(root,order){
 const section=el('section',undefined,'terms-evidence client-auth'),state=order.client_authorization,title=el('h3','Autorización digital del cliente');section.append(title);
 const line=text=>section.append(el('p',text));
 if(!state)line('Todavía no se ha enviado ningún enlace de autorización para esta orden.');
 else{const badge=el('span',state.status_label,'client-auth-state');badge.dataset.status=state.status;const top=el('p');top.append(badge);section.append(top);line('Enviado a '+state.recipient+' · '+formatOrderDate(state.created_at)+(state.mail_result&&state.mail_result!=='sent'?' · el correo no se pudo enviar':''));
  if(state.evidence){const names={service:'Diagnóstico y servicio',operating_system:'Sistema operativo',files:'Archivos y respaldos',data_operations:'Formateo o eliminación de datos'},list=el('ul',undefined,'client-auth-list');for(const key of Object.keys(names)){const value=state.evidence.decisions[key];if(!value)continue;const item=el('li'),mark=el('b',value==='authorized'?'AUTORIZADO':'NO AUTORIZADO');mark.dataset.value=value;item.append(el('span',names[key]||key),mark);list.append(item);}section.append(list);
   line('Firmada el '+formatOrderDate(state.signed_at)+' · '+(state.evidence.terms?'condiciones versión '+state.evidence.terms.version:'sin condiciones publicadas'));if(state.evidence.comment)line('Observaciones del cliente: '+state.evidence.comment);
   const hash=el('p','Huella de la evidencia: '+state.evidence_hash.slice(0,24)+'…','small');hash.title=state.evidence_hash;section.append(hash,documentAction('Comprobante de autorización (PDF)','document','/api/orders/'+order.id+'/client-authorization.pdf'));}
  else if(state.status==='pending')line('Pendiente de respuesta. El enlace caduca el '+formatOrderDate(state.expires_at)+'.');}
 const message=el('p','','message');message.setAttribute('role','status');
 const send=button(state?'Enviar un enlace nuevo':'Enviar enlace de autorización',async()=>{if(send.disabled)return;if(await confirmClose({title:'¿Enviar el enlace de autorización al cliente?',text:'Se enviará un correo a la dirección registrada en la orden'+(state&&state.status==='pending'?'; el enlace anterior dejará de funcionar':'')+'. El cliente deberá comprobar su identidad antes de decidir.',keep:'Cancelar',discard:'Enviar enlace'})!=='discard')return;
   send.disabled=true;send.dataset.loading='true';message.textContent='';try{const result=await api('/api/orders/'+order.id+'/client-authorization',{action:'send'});toast(result.message,result.result==='sent'?'success':'error',undefined,{title:'Autorización digital'});
     const box=el('div',undefined,'client-auth-link'),field=el('input'),copy=button('Copiar enlace',async()=>{try{await navigator.clipboard.writeText(result.url);copy.textContent='Copiado';}catch{field.select();}},'secondary');field.readOnly=true;field.value=result.url;field.setAttribute('aria-label','Enlace de autorización (se muestra solo esta vez)');box.append(el('small','Enlace del cliente (se muestra solo esta vez):'),field,copy);section.querySelector('.client-auth-link')?.remove();message.before(box);}
    catch(error){message.textContent=error.message;}finally{send.disabled=false;delete send.dataset.loading;}},'secondary');
 section.append(message,send);
 if(admin()){const auto=el('label',undefined,'client-auth-auto'),box=el('input');box.type='checkbox';box.checked=!!order.client_authorization_auto;box.onchange=async()=>{box.disabled=true;try{await api('/api/client-authorization/settings',{auto:box.checked});toast(box.checked?'El enlace de autorización se enviará al registrar cada orden nueva.':'Envío automático desactivado.','success');}catch(error){box.checked=!box.checked;toast(error.message,'error');}finally{box.disabled=false;}};auto.append(box,el('span','Enviar este enlace automáticamente al registrar cada orden nueva'));section.append(auto);}
 section.append(el('small','No es una firma electrónica certificada: registra las decisiones del cliente con su fecha, hora y el método de verificación (enlace, últimos cuatro dígitos y código por correo).','client-auth-note'));
 root.append(section);
}
