function cashReason(){return new Promise(resolve=>{const dialog=smallDialog('Anular depósito'),form=el('form',undefined,'cash-reason'),area=el('textarea'),msg=el('p','','inv-form-message');area.rows=3;area.maxLength=300;area.required=true;msg.setAttribute('role','alert');
 const box=el('label',undefined,'inv-field');box.append(el('span','Motivo de la anulación'),area);const ok=el('button','Anular depósito','primary');ok.type='submit';const bar=el('div',undefined,'dialog-actions');bar.append(button('Cancelar',()=>dialog.close(),'secondary'),ok);form.append(box,msg,bar);dialog.append(form);area.focus();let done=false;
 form.addEventListener('submit',event=>{event.preventDefault();if(area.value.trim().length<5){msg.textContent='Indica el motivo (al menos 5 caracteres).';return;}done=true;dialog.close();resolve(area.value.trim());});dialog.addEventListener('close',()=>{if(!done)resolve('');});});}
// Confirmar un depósito: fecha, número de comprobante y archivo (JPG, PNG o PDF hasta 5 MB). El archivo viaja por partes.
function cashConfirmDialog(d,panel){const dialog=smallDialog('Confirmar depósito');dialog.classList.add('cash-confirm');const form=el('form',undefined,'cash-confirm-form'),msg=el('p','','inv-form-message'),progress=el('p','','system-muted');msg.setAttribute('role','alert');progress.setAttribute('role','status');form.noValidate=true;
 const today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Guayaquil'}).format(new Date()),date=el('input'),voucher=el('input'),file=el('input');date.type='date';date.value=today;date.max=today;voucher.maxLength=40;voucher.autocomplete='off';file.type='file';file.accept='image/jpeg,image/png,application/pdf';
 const f=(label,node,hint)=>{const box=el('label',undefined,'inv-field');box.append(el('span',label),node);if(hint)box.append(el('small',hint));form.append(box);};
 form.append(el('p',quoteMoney(d.amount_cents)+' en '+d.account.label,'cash-confirm-what'));f('Fecha del depósito',date);f('Número de comprobante bancario',voucher);f('Foto o archivo del comprobante',file,'JPG, PNG o PDF de hasta 5 MB.');
 const ok=el('button','Confirmar depósito realizado','primary');ok.type='submit';const bar=el('div',undefined,'dialog-actions');bar.append(button('Cancelar',()=>dialog.close(),'secondary'),ok);form.append(msg,progress,bar);dialog.append(form);voucher.focus();
 form.addEventListener('submit',async event=>{event.preventDefault();msg.textContent='';const chosen=file.files[0];
  if(!voucher.value.trim()){msg.textContent='Indica el número del comprobante.';voucher.focus();return;}if(!chosen){msg.textContent='Adjunta la foto o el archivo del comprobante.';file.focus();return;}
  if(!['image/jpeg','image/png','application/pdf'].includes(chosen.type)){msg.textContent='Solo se aceptan JPG, PNG o PDF.';return;}if(chosen.size>5*1024*1024){msg.textContent='El archivo pesa '+(chosen.size/1048576).toFixed(1).replace('.',',')+' MB: el máximo es 5 MB.';return;}
  ok.disabled=true;try{const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]||'');r.onerror=()=>reject(new Error('No se pudo leer el archivo.'));r.readAsDataURL(chosen);});
   const size=1400000,parts=Math.max(1,Math.ceil(data.length/size));let upload='';for(let i=0;i<parts;i++){progress.textContent='Subiendo comprobante: parte '+(i+1)+' de '+parts+'…';const out=await api('/api/cash/upload',{upload_id:upload,part:String(i),total:String(parts),data:data.slice(i*size,(i+1)*size)});upload=out.upload_id;}
   progress.textContent='Verificando…';await api('/api/cash/deposits/'+d.id,{action:'confirm',deposit_date:date.value,voucher_number:voucher.value.trim(),upload_id:upload,file_name:chosen.name});dialog.close();toast('Depósito confirmado.','success');cashDay(panel);}
  catch(error){progress.textContent='';msg.textContent=error.message+' '+Object.values(error.fields||{}).join(' ');ok.disabled=false;}});}
async function cashHistory(panel){panel.replaceChildren(el('p','Cargando…','empty-module'));const h=cashState.hist;let data;try{data=await api('/api/cash/history?'+new URLSearchParams({user:h.user,status:h.status,from:h.from,to:h.to}));}catch(error){panel.replaceChildren(el('p',error.message,'empty-module'));return;}
 panel.replaceChildren();const bar=el('form',undefined,'cash-hist-bar');bar.addEventListener('submit',e=>e.preventDefault());const fld=(label,node)=>{const b=el('label',undefined,'inv-field');b.append(el('span',label),node);bar.append(b);return node;};
 if(data.people.length){const who=fld('Persona',el('select'));who.add(new Option('Todas',''));for(const p of data.people)who.add(new Option(p.name,String(p.id)));who.value=h.user;who.addEventListener('change',()=>{h.user=who.value;cashHistory(panel);});}
 const st=fld('Depósitos',el('select'));st.add(new Option('Todos',''));for(const[k,v]of Object.entries(data.statuses))st.add(new Option(v,k));st.value=h.status;st.addEventListener('change',()=>{h.status=st.value;cashHistory(panel);});
 for(const[key,label]of [['from','Desde'],['to','Hasta']]){const d=fld(label,el('input'));d.type='date';d.value=h[key];d.addEventListener('change',()=>{h[key]=d.value;cashHistory(panel);});}panel.append(bar);
 if(!data.rows.length){panel.append(el('p','No hay cierres con estos filtros.','empty-module'));return;}
 const list=el('ul',undefined,'inv-list');for(const r of data.rows){const li=el('li'),row=button('',()=>{cashState.tab='dia';cashState.day=r.day;cashState.user=r.user_id===currentUser.id?'':String(r.user_id);renderCash();},'inv-row cash-hist-row');const who=el('div',undefined,'inv-row-who');who.append(el('strong',dashboardDate(r.day)+' · '+r.person),el('small','Esperado '+quoteMoney(r.expected_cash_cents)+' · contado '+quoteMoney(r.counted_cash_cents)+(r.difference_cents?' · diferencia '+quoteMoney(r.difference_cents):'')));
  const sums=el('div',undefined,'cash-hist-sums');for(const[k,v]of Object.entries(r.deposit_summary))if(v&&k!=='anulado')sums.append(invoiceChip({pendiente:'pendiente',depositado:'enviado',conciliado:'autorizado'}[k],depositStates[k]+' '+quoteMoney(v)));if(!sums.childElementCount)sums.append(invoiceChip('pendiente','Sin depósitos'));
  row.append(who,sums);row.setAttribute('aria-label','Abrir la caja de '+r.person+' del '+dashboardDate(r.day));li.append(row);list.append(li);}panel.append(list);}
